/**
 * 提示词对照工作台（设计文档 `docs/执行设计-v1.md` §9）。
 *
 * 三栏：第 N 集剧本 / 本集提示词 / 批注。
 *
 * ⚠️ 和剧本批注（`dsh-novel-script`）的关系：**左右互换**。
 *    那边锚点是小说的行、作业区是剧本的段落；这边锚点是剧本的行（只读参考，
 *    一份，不随版本变）、作业区是提示词（随版本走，按清单切成一个个块）。
 *    所以：
 *      · 左边**不可划词、不可批注**，只做"高亮当前块引用的那几行"；
 *      · 划词和批注全在**中栏**，批注挂的是**块的位置序号**（不是正文里的 Block 号）。
 *
 * 这一版**不判断剧情内容**：块从哪里切、和剧本对不对得上，完全照清单里的
 * `promptLines` / `scriptRanges` 用；判断"对应得对不对"是人的事。
 *
 * 交互：
 *   · 悬停/点中栏某块 → 左栏高亮这一块 `scriptRanges` 覆盖的剧本行；
 *   · 悬停左栏某行 → 中栏高亮引用了这一行的块；
 *   · 在提示词里划词 → 批注框跟着选区浮出来（按住 Ctrl 可连选几处不连续的）；
 *   · 点批注卡上的「定位」→ 跳到那一块；
 *   · 清单与提示词对不上 / 文件缺失 → 顶部醒目地说出来，不猜。
 *
 * ⚠️ 没有的东西（设计文档 §2.2 明确不做，别手痒补回来）：
 *    覆盖竖条 / coverBar、漏拍统计、任何"剧本上下文"字段。
 */

import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type CSSProperties,
  type MouseEvent,
  type ReactNode,
} from 'react'
import { manifestPath, promptPath, scriptPath, type Annotation, type AnnotationRegion } from '../shared/protocol.ts'
import { makeAnnotation, nextAnnotationSeq } from '../shared/validate.ts'
import {
  toAnnotations,
  useAnnotations,
  useBlocks,
  useScript,
  useWorkbench,
  type BlockView,
} from './data.ts'
import { loadAnnotations, saveAnnotations } from './annotations.ts'
import { useWorkbenchGeometry } from './geometry.ts'
import type { WorkspaceFilesFace } from './workspace.ts'

/** 列宽约束：两侧最小 180，中间至少留 260。 */
const MIN_SIDE = 180
const MIN_MID = 260

/** 浮动批注框的尺寸（用来把它夹进视口，免得贴边被切）。 */
const POPUP_W = 320
const POPUP_H = 210

/**
 * 一处区域的显示名：`块 6` / `块 3–7`。
 *
 * ⚠️ 这里用的是**块的位置序号**（清单里的第几块，1 基），
 *    和提示词正文里 agent 自己写的 `Block N` 没有任何关系（设计文档 §4.3）。
 */
function regionLabel(region: AnnotationRegion): string {
  const to = region.endParagraph ?? region.paragraph
  return to > region.paragraph ? `块 ${region.paragraph}–${to}` : `块 ${region.paragraph}`
}

/** 把几处区域摊平成块序号（去重、升序）—— 高亮和跳转都用它。 */
function blocksOfRegions(regions: readonly AnnotationRegion[]): number[] {
  const out = new Set<number>()
  for (const region of regions) {
    const to = region.endParagraph ?? region.paragraph
    for (let index = region.paragraph; index <= to; index += 1) out.add(index)
  }
  return [...out].sort((a, b) => a - b)
}

/** 一个块在提示词文件里占的那些行（1 基、闭区间）。 */
function linesOfBlock(block: BlockView): number[] {
  const out: number[] = []
  const [start, end] = block.promptLines
  for (let ln = start; ln <= end; ln += 1) out.push(ln)
  return out
}

/** 一个块引用的剧本行。`scriptRanges` 为 null 就是**剧本里没有对应**（新增）。 */
function scriptLinesOfBlock(block: BlockView): number[] {
  const out: number[] = []
  for (const [a, b] of block.scriptRanges ?? []) {
    for (let ln = a; ln <= b; ln += 1) out.push(ln)
  }
  return out
}

/** 一个块抬头右侧那枚小标：`→ 剧本 L12–L15` / `→ 剧本里没有对应`。 */
function scriptLabelOf(block: BlockView): string {
  const ranges = block.scriptRanges
  if (ranges === null || ranges.length === 0) return '→ 剧本里没有对应'
  return `→ 剧本 ${ranges.map(r => `L${r[0]}–L${r[1]}`).join('、')}`
}

/**
 * 这一块的 anchor 在提示词里**唯一命中**了没有（设计文档 §11）。
 *
 * ⚠️ 为什么必须按 anchor 判、而不是看"切出来的正文空不空"：
 *    清单里的 `promptLines` 是工具算的、程序直接信；界面能做的机械校验只有
 *    "首行在文件里能不能唯一命中"。找不到 / 命中多处的块，界面上只说这一块
 *    「清单与文件对不上」，**其余块照常渲染**（不崩、不空白）。
 *
 * 判据只有一条：**清单说的那一行，内容是不是它自己的 anchor**。
 *
 * ⚠️ 2026-09-14 连着踩了两次，两条都记下来了：
 *   ① 早先的实现是"把各块的行按行号拼回文件，再用 locateAnchor 找 anchor" —— 每块的首行
 *      拼回去永远等于它自己的 anchor，所以**永远通过**，这条界面提示等于死的。
 *   ② 补上之后又加了第二条"anchor 必须在全文件里唯一" —— **太严**：提示词块的首行常常是
 *      `场景：@某地_某时` 这种内容行，**连续的几块常在同一场景里，首行天然重复**。
 *      实测另一个工作区的第 1 集：9 块里 8 块的 anchor 重复出现（`场景：@火车站公厕外_夜`
 *      出现 3 次、`…_深夜` 出现 5 次），界面于是整片报"对不上"，而清单其实是**完全自洽**的。
 *      **唯一性只对"按 anchor 搜索"（`write_manifest`）是必需的；界面手上有准确行号，
 *      渲染根本不需要它。**
 *
 * 所以这里只比一行，不重建文件、不要求唯一 —— 判据越少越不会误报。
 */
function blocksMissingAnchor(blocks: readonly BlockView[]): Set<number> {
  const out = new Set<number>()
  for (const block of blocks) {
    // `block.lines[0]` 就是文件里 `promptLines[0]` 那一行（useBlocks 是按清单切的）
    if (block.lines[0] !== block.anchor) out.add(block.index)
  }
  return out
}

/**
 * 把滚动容器里的目标滚到可视区**偏上**的位置 —— 上方留一点上下文，不贴顶、也不居中。
 *
 * ⚠️ 主人 2026-09-14 连着纠了两次：
 *    ① 原来用 `scrollIntoView({ block: 'center' })`，目标被推到**中间** —— 上面空一大片、
 *       下面几行反而被切掉；
 *    ② 改成"贴顶"也不合适 —— 想看到目标**上面两行左右**的内容（对照时那两行常常正是上下文）。
 *
 * 留白口径统一成"**目标上方留 N 行**"：N × 目标元素的**计算行高**。
 *   · 左栏剧本行是单行元素，行高就是它的高度；
 *   · 中栏提示词块是个很高的容器，但它的 `line-height` 仍是正文字号的行高 ——
 *     所以同一个 `offsetLines: 2` 在两边都得到"上面留两行"的观感，而不是"按块高折算半个屏幕"。
 *   · `lineHeight` 拿不到数字（`normal`）时退回元素自身高度，保证不会算出 NaN 把滚动搞飞。
 *
 * 用 **rect 差值**算，不用 `el.offsetTop`：`offsetTop` 是相对**最近的定位祖先**的，
 * 而滚动容器并不保证是定位元素（当初为覆盖竖条加过 `position: relative`，后来删掉了）——
 * 那样算出来的偏移会悄悄差一大截，而且只在某些列宽下才看得出来。
 *
 * @param box - 滚动容器。
 * @param selector - 目标元素的 CSS 选择器（`[data-ln="12"]` / `[data-paragraph="3"]`）。
 * @param offsetLines - 目标上方留几行（默认 2）。
 */
function scrollTargetToTop(box: HTMLElement | null, selector: string, offsetLines = 2): void {
  const el = box?.querySelector<HTMLElement>(selector)
  if (box === null || el === null || el === undefined) return
  const rect = el.getBoundingClientRect()
  const delta = rect.top - box.getBoundingClientRect().top
  const parsed = Number.parseFloat(window.getComputedStyle(el).lineHeight)
  const lineHeight = Number.isFinite(parsed) && parsed > 0 ? parsed : rect.height
  box.scrollTo({ top: box.scrollTop + delta - lineHeight * offsetLines, behavior: 'smooth' })
}

/**
 * 未登记时给主人复制的那句话。
 *
 * 写得具体是因为 agent 需要知道**完整流程**：建目录、拷剧本（字节复制）、
 * 一集一集调工具、先跑第 1 集。
 *
 * ⚠️ 两个工具的分工别写错：正文与清单是**一次生成**的
 *    （`prompt_compare_write_episode` 同时写 `提示词/` 与 `清单/` 两个文件），
 *    `prompt_compare_write_manifest` 是"只重算/重写清单"时用的补刀工具。
 */
const REGISTER_PROMPT = [
  '请把这个工作区建成「提示词对照工作台」。步骤：',
  '',
  '1. 在工作区根目录下建 `对照工作台/` 文件夹，里面再建 `剧本/`。',
  '2. 把剧本稿**拷贝**一份（用 Copy-Item，字节复制，不要用 Get-Content/Set-Content）',
  '   到 `对照工作台/剧本/第1集剧本.txt`（一集一个文件，集号用阿拉伯数字）。',
  '   用户原始的稿子一个字都不要动。',
  '3. 提示词按版本放：`对照工作台/v1/提示词/第1集提示词.txt`。',
  '   自己先把提示词写出来放进去（这一版就是 v1，目录名就写 v1）。',
  '4. 逐集登记：把提示词正文按"块"切开，每块判断它对应剧本的哪几行，',
  '   然后用 prompt_compare_write_episode 工具提交（一次一集）。',
  '   · 块 = 可独立高亮和批注的一段文字，内部可以多行，但**不能有空白行**；',
  '   · 剧本里没有对应的块，scriptRanges 写 null（比如新增的过场、空镜提示）；',
  '   · 只给"每块首行 + 对应剧本行号"，**不要逐字复述正文** —— 行号由工具算；',
  '   · 工具一次写出 `v1/提示词/第1集提示词.txt` 与 `v1/清单/第1集清单.txt` 两个文件，',
  '     不要自己手写这两个文件（行号、块编号、文件生成都由工具负责）；',
  '   · 只想重算某一集的清单时，用 prompt_compare_write_manifest。',
  '5. **先只做第 1 集**，让我在工作台看一眼，确认没问题再继续第 2 集，然后才是剩下的。',
].join('\n')

/**
 * 一个块的正文。
 *
 * @param block - 这一块。
 * @param missing - 它的 anchor 在提示词里找不到（§11）。
 *
 * 两条规则：
 *   · `missing` → 正文位置只写一句「清单与文件对不上」，**其余块照常渲染**；
 *   · 否则**从第 2 行开始渲染**（`slice(1)`）：第 1 行就是抬头里当标签显示的那一行
 *     （`── Block 1 | 14s ──`），再渲染一遍就重复了（设计文档 §9.2）。
 *     那一行是结构标记，没人会去批注它，不进选区没有损失；划词仍覆盖这一块
 *     `promptLines` 里其余的全部正文（含块内空行）。
 */
function blockBody(block: BlockView, missing: boolean): ReactNode {
  if (missing) return <span className="pc-para-bad">（清单与文件对不上：找不到这一块）</span>
  return block.lines.slice(1).map((line, i) => <span key={i} className="pc-para-line">{line}</span>)
}

export function Workbench({
  files,
  sessionId,
  sessionSource,
}: {
  files?: WorkspaceFilesFace
  sessionId?: string
  sessionSource?: 'current' | 'fallback' | 'none'
}): ReactNode {
  const wb = useWorkbench(files, sessionId)
  const scan = wb.scan

  /* ── 选哪一版、哪一集 ─────────────────────────────────────────────────
     默认打开**最新的一版**（审阅就是看最新的）和它的第 1 集。 */
  const [pickVersion, setPickVersion] = useState<string | null>(null)
  const [pickEpisode, setPickEpisode] = useState<number | null>(null)

  const version = useMemo(() => {
    const list = scan.versions
    if (list.length === 0) return null
    return list.find(v => v.version === pickVersion) ?? list[list.length - 1] ?? null
  }, [scan.versions, pickVersion])

  /**
   * 集号来自**版本目录里的集**，那是**超集**（提示词 / 清单 / 批注三个目录 ∪ 剧本目录）。
   *
   * ⚠️ 所以会出现 `hasScript=true && hasPrompt=false` 的集：剧本切好了、提示词还没写。
   *    那不是错误，是**正常中间状态**，中栏要直说"这一版还没写提示词"，别把它当异常
   *    （这时 `useBlocks` 会说"缺提示词文件：…"，那句话太硬，见下面 middleEmpty 的处理）。
   *    实测两侧 35/35 一一对应（设计文档 §4），所以正常做完的版本不会出现这种集。
   */
  const episode = useMemo(() => {
    const list = version?.episodes ?? []
    if (list.length === 0) return null
    return list.find(e => e.episode === pickEpisode) ?? list[0] ?? null
  }, [version, pickEpisode])

  /** 上一集 / 下一集（主人要的两个按钮）。 */
  const episodeNav = useMemo(() => {
    const list = version?.episodes ?? []
    const index = episode === null ? -1 : list.findIndex(e => e.episode === episode.episode)
    return {
      prev: index > 0 ? list[index - 1] : undefined,
      next: index >= 0 && index < list.length - 1 ? list[index + 1] : undefined,
    }
  }, [version, episode])

  /* ⚠️ 传给数据 hook 的是**版本目录名**（`v1`），不是去掉 v 的版本号（`1`）：
     拼路径的函数按 `对照工作台/<目录名>/…` 拼。混淆过一次，
     表现是"清单文件找不到：对照工作台/1/清单/…"，中栏整个空白。
     hook 的签名要的是 `string` / `number`，所以这里显式兜底成空串 / 0 ——
     空串与 0 在 hook 里等于"还没选集"，是 idle，不会去读文件、也不报错。 */
  const ep = episode?.episode ?? 0
  const vdir = version?.dir ?? ''
  const script = useScript(files, sessionId, ep)
  const blk = useBlocks(files, sessionId, vdir, ep)
  const anno = useAnnotations(sessionId, vdir, ep)

  /**
   * 这一集中栏为什么画不出块。
   *
   * ⚠️ **必须放在上面三个 hook 之后**：它读 `blk.error` / `ep` / `vdir`，而这三个都是
   *    `const` —— 写在前面就是 TDZ（运行时 "Cannot access 'blk' before initialization"），
   *    表现是整个工作台被错误边界接住、只剩一句话。2026-09-14 踩过一次。
   *
   * 优先级：**缺提示词文件**（超集里还没登记的集，属于正常中间状态）→ 其余按 hook 的话说。
   * 缺剧本文件的集不用特殊处理：`useScript` 的 `error` 里本来就带完整路径，左栏直接显示。
   */
  const promptMissing = episode !== null && !episode.hasPrompt
  const middleEmpty = promptMissing
    ? `这一版还没写这一集的提示词 —— 让 AI 把它放进 ${promptPath(vdir, ep)}`
    : (blk.error || '读不到这一集提示词')

  /* ── 批注栏：按集看 / 全部看 ────────────────────────────────────────────
     批注是**按集一个文件**存的，所以"全部"要把这一版每一集的批注都读回来
     （一集一次请求，并行发；本地很快）。只有真的切到"全部"才去读，
     免得每次打开工作台都打几十个请求。 */
  const [annoScope, setAnnoScope] = useState<'episode' | 'all'>('episode')
  const [allAnnotations, setAllAnnotations] = useState<Record<number, Annotation[]>>({})
  const [allError, setAllError] = useState('')
  const [allNonce, setAllNonce] = useState(0)

  useEffect(() => {
    if (annoScope !== 'all' || sessionId === undefined || sessionId === '' || version == null) return
    const dir = version.dir
    const list = version.episodes
    if (list.length === 0) return
    let alive = true
    setAllError('')
    void Promise.all(list.map(async (item) => {
      const result = await loadAnnotations(sessionId, dir, item.episode)
      return [item.episode, result] as const
    })).then((pairs) => {
      if (!alive) return
      const next: Record<number, Annotation[]> = {}
      const errors: string[] = []
      for (const [episodeNo, result] of pairs) {
        if (result.ok) next[episodeNo] = toAnnotations(result.annotations)
        else errors.push(`第 ${episodeNo} 集：${result.error}`)
      }
      setAllAnnotations(next)
      if (errors.length > 0) setAllError(errors.join('；'))
    }).catch((err: unknown) => {
      if (alive) setAllError(err instanceof Error ? err.message : String(err))
    })
    return () => { alive = false }
  }, [annoScope, sessionId, version, allNonce])

  /** "全部"模式下总共多少条。 */
  const allCount = useMemo(
    () => Object.values(allAnnotations).reduce((n, list) => n + list.length, 0),
    [allAnnotations],
  )

  /* ── 高亮联动（这一版的核心交互，左右**双向**）────────────────────────
     方向一：悬停/点中栏某块 → 左栏高亮这一块引用的剧本行。
     方向二：悬停左栏某行 → 中栏高亮引用了这一行的块。
     "钉住"的是**一组块号**（可以是不连续的几个 —— Ctrl 多选/点批注定位的结果）。 */
  const [hoverBlock, setHoverBlock] = useState<number | null>(null)
  const [pinnedBlocks, setPinnedBlocks] = useState<number[]>([])
  const [hoverLine, setHoverLine] = useState<number | null>(null)

  /** 按块号取块（点选/定位/高亮都要用）。 */
  const blockByIndex = useMemo(() => {
    const map = new Map<number, BlockView>()
    for (const block of blk.blocks) map.set(block.index, block)
    return map
  }, [blk.blocks])

  /** 清单里的 anchor 在提示词里找不到（或命中多处）的块 —— 只影响那一块的显示。 */
  const missingAnchor = useMemo(() => blocksMissingAnchor(blk.blocks), [blk.blocks])

  /** 当前"正在看"的块：钉住优先，否则看悬停的那一块。 */
  const activeBlocks = useMemo<BlockView[]>(() => {
    if (pinnedBlocks.length > 0) {
      return pinnedBlocks.map(index => blockByIndex.get(index)).filter((b): b is BlockView => b !== undefined)
    }
    if (hoverBlock === null) return []
    const one = blockByIndex.get(hoverBlock)
    return one === undefined ? [] : [one]
  }, [blockByIndex, pinnedBlocks, hoverBlock])

  /** 钉住的块引用的剧本行（左栏要滚到哪儿、也要高亮这几行）。 */
  const pinnedLines = useMemo(() => {
    const out = new Set<number>()
    if (pinnedBlocks.length === 0) return out
    for (const block of activeBlocks) {
      for (const ln of scriptLinesOfBlock(block)) out.add(ln)
    }
    return out
  }, [activeBlocks, pinnedBlocks])

  /** 悬停左栏某行 → 引用这一行的块（方向二）。 */
  const hoverBlockIndices = useMemo(() => {
    const out = new Set<number>()
    if (hoverLine === null) return out
    for (const block of blk.blocks) {
      const [start, end] = block.promptLines
      if (hoverLine >= start && hoverLine <= end) out.add(block.index)
    }
    return out
  }, [blk.blocks, hoverLine])

  /** 左栏要高亮的行：钉住某块时听钉住的，否则听悬停那一行的块。 */
  const highlightLines = useMemo(() => {
    const out = new Set<number>()
    if (pinnedLines.size > 0) {
      for (const ln of pinnedLines) out.add(ln)
      return out
    }
    for (const block of activeBlocks) {
      for (const ln of scriptLinesOfBlock(block)) out.add(ln)
    }
    return out
  }, [pinnedLines, activeBlocks])

  /* ── 划词 → 待写的批注 ──────────────────────────────────────────────── */
  const promptRef = useRef<HTMLDivElement | null>(null)
  const scriptRef = useRef<HTMLDivElement | null>(null)
  /** 批注框（跟着选区浮出来的那个）的 DOM，用来判断"点框外"。 */
  const popRef = useRef<HTMLDivElement | null>(null)
  /** 待写的批注：已经选了哪几处（Ctrl 累积）、批注框浮在哪儿、框是否已经弹出来。 */
  const [pending, setPending] = useState<{
    regions: AnnotationRegion[]
    x: number
    y: number
    /** false = 还按着 Ctrl 在连选：**不弹输入框**，只靠块上的深底色报数。 */
    open: boolean
  } | null>(null)
  const [problem, setProblem] = useState('')
  const [toast, setToast] = useState('')

  /**
   * 手动刷新 = 四个 hook 各重读一次（见下面那颗 ⟳ 按钮）。
   *
   * ⚠️ **四个都要调**：`useScript` / `useBlocks` 的依赖是
   * (files, sessionId, version, episode)，只看这些的话刷新时它们一个都没变 ——
   * 只调 `wb.reload()` 那两个**不会重读**（刷新等于没刷）。
   *
   * 曾经用"给三栏换 key 强制重挂"兜过一阵子，副作用是刷新会把选中的版本/集
   * 重置回默认；四个 hook 都有 reload 之后就不需要那种做法了。
   */

  useEffect(() => {
    if (toast === '') return
    const timer = window.setTimeout(() => setToast(''), 2600)
    return () => window.clearTimeout(timer)
  }, [toast])

  /**
   * 松手后读选区。
   *
   * 三条规则（沿用剧本批注那边实测下来的结论）：
   *   · **不按 Ctrl**：这一划就是新的全部选择（替换掉之前选的），**立刻弹输入框**；
   *   · **按住 Ctrl/Cmd**：把这一处**并进去** —— 这就是"多选不连续的几个地方"；
   *   · 按住 Ctrl 连选期间**不弹输入框**：这段时间屏幕上**只有一个反馈**：
   *     被选中的块带一层更深的底色（`.pc-para-pending`），**松开 Ctrl 之后再弹框**
   *     （见下面的 keyup 效果）。
   *     ⚠️ 不要在选区旁边飘提示文字 —— 它就压在提示词上，会把接下来要划的那几行挡住。
   * 每一处都记成"块范围"（连续跨块算一处），因为一个块是"一行一块"还是
   * "多行一块"由 agent 决定（设计文档 §4.3）。
   */
  const onPromptMouseUp = useCallback((e: MouseEvent<HTMLDivElement>): void => {
    const multi = e.ctrlKey || e.metaKey
    const releaseX = e.clientX
    const releaseY = e.clientY
    window.setTimeout(() => {
      const selection = window.getSelection()
      if (selection === null || selection.isCollapsed || selection.rangeCount === 0) return
      const range = selection.getRangeAt(0)
      const container = promptRef.current
      if (container === null || !container.contains(range.commonAncestorContainer)) return
      const startEl = elementOf(range.startContainer, container)
      const endEl = elementOf(range.endContainer, container)
      if (startEl === null || endEl === null) return
      const startNo = Number(startEl.dataset.paragraph)
      const endNo = Number(endEl.dataset.paragraph)
      if (!Number.isInteger(startNo) || !Number.isInteger(endNo) || startNo < 1 || endNo < 1) return
      const paragraph = Math.min(startNo, endNo)
      const endParagraph = Math.max(startNo, endNo)
      const quote = selection.toString().trim()
      if (quote === '') return
      const region: AnnotationRegion = {
        paragraph,
        ...(endParagraph > paragraph ? { endParagraph } : {}),
        quote,
      }
      /* 批注框**跟着选区走**（不该固定在批注栏里）。
         用松手时的指针位置，多选时不会因为旧选区矩形而跳来跳去。 */
      const x = Math.min(Math.max(8, releaseX), Math.max(8, window.innerWidth - POPUP_W - 12))
      const y = Math.min(Math.max(8, releaseY + 14), Math.max(8, window.innerHeight - POPUP_H - 12))
      setPending(prev => {
        const list = multi && prev !== null ? [...prev.regions] : []
        const duplicate = list.some(r => r.paragraph === region.paragraph
          && r.endParagraph === region.endParagraph && r.quote === region.quote)
        if (!duplicate) list.push(region)
        /* 按住 Ctrl 时 open:false —— 框先不弹，等松开 Ctrl 再弹。 */
        return { regions: list, x, y, open: !multi }
      })
      setProblem('')
      if (multi) {
        /* 多选期间把选区清掉，方便接着划下一处（否则第二处会被上一处的选区干扰）。 */
        window.getSelection()?.removeAllRanges()
      }
    }, 10)
  }, [])

  /**
   * Ctrl 连选期间那几处覆盖的块号。
   *
   * 为什么需要它：连选时输入框是**不弹**的，而选区又被 removeAllRanges 清掉了 ——
   * 屏幕上就没有任何"我到底选了哪几处"的反馈。所以给这些块单独加一层底色，
   * 这也是连选期间**唯一**的反馈（不再飘提示文字，见 onPromptMouseUp 的说明）。
   */
  const pendingBlocks = useMemo(() => {
    const out = new Set<number>()
    if (pending === null) return out
    for (const region of pending.regions) {
      const end = region.endParagraph ?? region.paragraph
      for (let n = region.paragraph; n <= end; n += 1) out.add(n)
    }
    return out
  }, [pending])

  /* 松开 Ctrl/Cmd → 把输入框弹出来：多选结束。
     焦点不在窗口里时浏览器可能不给 keyup，所以另挂 blur 兜底，提示条本身也可以点开。 */
  useEffect(() => {
    if (pending === null || pending.open) return
    const openIt = (): void => setPending(prev => (prev === null || prev.open ? prev : { ...prev, open: true }))
    const onKeyUp = (e: KeyboardEvent): void => { if (e.key === 'Control' || e.key === 'Meta') openIt() }
    document.addEventListener('keyup', onKeyUp)
    window.addEventListener('blur', openIt)
    return () => {
      document.removeEventListener('keyup', onKeyUp)
      window.removeEventListener('blur', openIt)
    }
  }, [pending])

  const closePending = useCallback((): void => {
    setPending(null)
    setProblem('')
  }, [])

  const submitAnnotation = useCallback((): void => {
    if (pending === null || pending.regions.length === 0) return
    const text = problem.trim()
    if (text === '') { setToast('先写一下问题'); return }
    const seq = nextAnnotationSeq(anno.annotations)
    const created = makeAnnotation(seq, pending.regions, text)
    void anno.save([...anno.annotations, created]).then((ok) => {
      if (!ok) return
      setPending(null)
      setProblem('')
      window.getSelection()?.removeAllRanges()
      setToast('批注已保存')
    })
  }, [anno, pending, problem])

  /* 批注框开着时：Esc 关掉；点框外也关掉（点框内不关）。
     ⚠️ **在提示词栏里按下鼠标不算"点框外"** —— 那是要接着选下一处
     （Ctrl 多选时必须这样，否则一点就关、第二处就并不进来了）。
     ⚠️ 还按着 Ctrl 连选（open=false）时**不关**：那是选到一半，点别处多半是误触；
        想放弃按 Esc 就行。 */
  useEffect(() => {
    if (pending === null) return
    const open = pending.open
    const onKey = (e: KeyboardEvent): void => { if (e.key === 'Escape') closePending() }
    const onDown = (e: globalThis.MouseEvent): void => {
      if (!open) return
      const box = popRef.current
      if (box !== null && e.target instanceof Node && box.contains(e.target)) return
      if (e.target instanceof Element && e.target.closest('.pc-col-prompt') !== null) return
      closePending()
    }
    document.addEventListener('keydown', onKey)
    document.addEventListener('mousedown', onDown)
    return () => {
      document.removeEventListener('keydown', onKey)
      document.removeEventListener('mousedown', onDown)
    }
  }, [pending, closePending])

  /** 跨集跳转：先切集，等这一集的块读出来再滚过去。 */
  const [pendingJump, setPendingJump] = useState<number[] | null>(null)

  /** 点批注卡 → 跳到它挂的那几块（中栏滚过去 + 左栏高亮）；跨集也能跳。 */
  const jumpToBlock = useCallback((episodeNo: number, regions: readonly AnnotationRegion[]): void => {
    const targets = blocksOfRegions(regions)
    const first = targets[0]
    if (first === undefined) return
    if (episode?.episode === episodeNo) {
      setPinnedBlocks(targets)
      requestAnimationFrame(() => {
        scrollTargetToTop(promptRef.current, `[data-paragraph="${first}"]`)
      })
      return
    }
    setPickEpisode(episodeNo)
    setPendingJump(targets)
  }, [episode])

  useEffect(() => {
    const first = pendingJump?.[0]
    if (pendingJump === null || first === undefined || blk.phase !== 'ready') return
    setPinnedBlocks(pendingJump)
    setPendingJump(null)
    requestAnimationFrame(() => {
      scrollTargetToTop(promptRef.current, `[data-paragraph="${first}"]`)
    })
  }, [pendingJump, blk.phase])

  /**
   * 选中提示词某几块 → 左栏剧本**自动滚到对应位置**。
   *
   * 只在**点选 / 定位**（`pinnedBlocks`）时滚；悬停不滚 ——
   * 鼠标扫过块时剧本跟着乱跳会很难读。
   */
  useEffect(() => {
    if (pinnedBlocks.length === 0) return
    let first = Number.POSITIVE_INFINITY
    for (const index of pinnedBlocks) {
      const block = blockByIndex.get(index)
      if (block === undefined) continue
      for (const [a] of block.scriptRanges ?? []) first = Math.min(first, a)
    }
    if (!Number.isFinite(first)) return
    requestAnimationFrame(() => {
      scrollTargetToTop(scriptRef.current, `[data-ln="${first}"]`)
    })
  }, [pinnedBlocks, blockByIndex])

  /**
   * 删除一条批注。
   *
   * 批注是**按集一个文件**存的，所以"全部"模式下要写回**它所属那一集**的文件，
   * 不能一股脑写当前集。
   */
  const deleteOne = useCallback((episodeNo: number, id: string): void => {
    if (episode?.episode === episodeNo) {
      void anno.save(anno.annotations.filter(a => a.id !== id)).then((ok) => {
        if (ok) setToast('批注已删除')
      })
      return
    }
    const dir = version?.dir
    if (sessionId === undefined || sessionId === '' || dir === undefined) return
    const list = (allAnnotations[episodeNo] ?? []).filter(a => a.id !== id)
    void saveAnnotations(sessionId, dir, episodeNo, list).then((result) => {
      if (result.ok) {
        setAllAnnotations(prev => ({ ...prev, [episodeNo]: result.annotations }))
        setToast('批注已删除')
      } else {
        setAllError(result.error)
      }
    })
  }, [anno, allAnnotations, episode, version, sessionId])

  /** 这一轮要下发的条目（按集模式只有当前集；全部模式是所有集）。 */
  const sendItems = useMemo(() => {
    if (annoScope === 'episode') {
      return episode === null ? [] : anno.annotations.map(a => ({ episode: episode.episode, a }))
    }
    return Object.entries(allAnnotations)
      .flatMap(([ep, list]) => list.map(a => ({ episode: Number(ep), a })))
      .sort((x, y) => x.episode - y.episode
        || (x.a.regions?.[0]?.paragraph ?? 0) - (y.a.regions?.[0]?.paragraph ?? 0))
  }, [annoScope, episode, anno.annotations, allAnnotations])
  const sendCount = sendItems.length

  /**
   * 下发这一批批注。
   *
   * ⚠️ 为什么是"复制到剪贴板"而不是直接写官方输入框：`shell.overlay` 这个席位
   * 拿不到 `inputActions`（只有 `conversation.*` 那些席位有），所以浮层里
   * 没法定向写官方输入框。主人粘一下即可（这是流程的下一步）。
   *
   * ⚠️ 批注格式与剧本批注**完全一致**：只有"块 + 引文 + 问题"，
   *    **不带任何剧本上下文** —— agent 需要剧本时自己按清单去找（设计文档 §2.2）。
   */
  const sendBatch = useCallback((): void => {
    if (sendItems.length === 0) return
    const grouped = new Map<number, Annotation[]>()
    for (const item of sendItems) {
      const list = grouped.get(item.episode) ?? []
      list.push(item.a)
      grouped.set(item.episode, list)
    }
    const episodes = [...grouped.entries()].sort((x, y) => x[0] - y[0])
    const where = annoScope === 'all'
      ? `v${version?.version ?? '?'}（${episodes.length} 集）`
      : `v${version?.version ?? '?'} 第 ${episode?.episode ?? '?'} 集`
    const body: string[] = []
    for (const [episodeNo, list] of episodes) {
      body.push(`【第 ${episodeNo} 集】`)
      /* ⚠️ 路径点名到文件（设计文档 §9.5）：agent 改稿时要自己按清单去读剧本
         （批注里**不带剧本原文**，§2.2），所以三个文件的路径都要写清楚。 */
      body.push(`清单：${manifestPath(version?.dir ?? '', episodeNo)}（里面是"块 → 剧本行号"的对应）`)
      body.push(`提示词：${promptPath(version?.dir ?? '', episodeNo)}`)
      body.push(`剧本（参考，不要改）：${scriptPath(episodeNo)}`)
      body.push('')
      for (const a of list) {
        const spans = (a.regions ?? [])
          .map(r => `${regionLabel(r)}「${r.quote.replaceAll('\n', ' ')}」`)
          .join('；')
        body.push(`· ${spans}——${a.problem}`)
      }
      body.push('')
    }
    const text = [
      `请按下面这批批注改提示词（${where}）：`,
      '',
      ...body,
      '改完请出新版本：',
      '1. 用 Copy-Item -Recurse 把这一版目录整份复制成新版本；',
      '2. 删掉新版本里复制过来的批注文件（不是写成空数组）；',
      '3. 对改过的每一集重新调 prompt_compare_write_episode；',
      '4. 写新版本的 变更记录.txt；',
      '5. 最后把这一版批注文件里已处理的条目改成 done: true、resolvedIn 写新版本号。',
    ].join('\n')
    void navigator.clipboard?.writeText(text).then(
      () => setToast(`已复制 ${sendItems.length} 条批注的指令 —— 粘到对话里发给 AI 即可`),
      () => setToast('复制失败（浏览器拒绝剪贴板）'),
    )
  }, [sendItems, annoScope, version, episode])

  /* ── 窗口几何（拖动 / 缩放 / 最小化 / 最大化）────────────────────────── */
  const geo = useWorkbenchGeometry()
  const wbRef = geo.ref
  const minBtnRef = useRef<HTMLButtonElement | null>(null)
  const isMin = geo.mode === 'min'
  /** 收起成胶囊时的高度：原来 24 太小，找不到也点不着（主人反馈）。
      36 = 样式里圆角 18 的两倍，正好是一枚完整的胶囊。 */
  const PILL_H = 36

  /* ── 键盘左右翻集 ──────────────────────────────────────────────────────
     ⚠️ 只在"没在输入/编辑"时生效：
       · 焦点在 input / textarea / select / 可编辑元素里 → 让给它们（别抢左右键）；
       · 批注框开着 → 让给批注框（主人特意提醒过"不要和编辑批注冲突"）。 */
  useEffect(() => {
    if (isMin) return
    const onKey = (e: KeyboardEvent): void => {
      if (e.key !== 'ArrowLeft' && e.key !== 'ArrowRight') return
      if (e.metaKey || e.ctrlKey || e.altKey || e.shiftKey) return
      const target = e.target as HTMLElement | null
      if (target?.closest('input, textarea, select, [contenteditable="true"]') != null) return
      if (pending !== null) return
      const next = e.key === 'ArrowLeft' ? episodeNav.prev : episodeNav.next
      if (next === undefined) return
      e.preventDefault()
      setPickEpisode(next.episode)
    }
    document.addEventListener('keydown', onKey)
    return () => { document.removeEventListener('keydown', onKey) }
  }, [episodeNav, pending, isMin])

  const startDrag = useCallback((e: MouseEvent<HTMLElement>, dragMode: 'move' | 'h' | 'w' | 'corner'): void => {
    const el = wbRef.current
    if (el === null) return
    const session = geo.beginDrag(el.getBoundingClientRect(), e.clientX, e.clientY, dragMode)
    document.body.classList.add(dragMode === 'move' ? 'pc-dragging' : 'pc-resizing')
    const onMove = (ev: globalThis.MouseEvent): void => session.apply(ev.clientX, ev.clientY)
    const onUp = (): void => {
      document.body.classList.remove('pc-dragging', 'pc-resizing')
      document.removeEventListener('mousemove', onMove)
      document.removeEventListener('mouseup', onUp)
      session.finish()
    }
    document.addEventListener('mousemove', onMove)
    document.addEventListener('mouseup', onUp)
    e.preventDefault()
  }, [geo, wbRef])

  /* ── 列宽 ──────────────────────────────────────────────────────────── */
  const colsRef = useRef<HTMLDivElement | null>(null)
  const [srcW, setSrcW] = useState(300)
  const [annoW, setAnnoW] = useState(300)

  const startColDrag = useCallback((e: MouseEvent<HTMLDivElement>, side: 'src' | 'anno'): void => {
    const startX = e.clientX
    const startW = side === 'src' ? srcW : annoW
    const total = colsRef.current?.clientWidth ?? 0
    const other = side === 'src' ? annoW : srcW
    const max = Math.max(MIN_SIDE, total - other - MIN_MID - 22)
    document.body.classList.add('pc-colresizing')
    const onMove = (ev: globalThis.MouseEvent): void => {
      const d = ev.clientX - startX
      const next = Math.min(Math.max(MIN_SIDE, startW + (side === 'src' ? d : -d)), max)
      if (side === 'src') setSrcW(next)
      else setAnnoW(next)
    }
    const onUp = (): void => {
      document.body.classList.remove('pc-colresizing')
      document.removeEventListener('mousemove', onMove)
      document.removeEventListener('mouseup', onUp)
    }
    document.addEventListener('mousemove', onMove)
    document.addEventListener('mouseup', onUp)
  }, [srcW, annoW])

  /* ── 窗口样式 ──────────────────────────────────────────────────────── */
  const wbStyle: CSSProperties = isMin
    ? {
        ...(geo.pillPos === null
          ? { right: geo.minRight ?? 12, top: geo.minTop ?? 56, width: 'auto' }
          : { left: geo.pillPos.x, top: geo.pillPos.y, width: 'auto' }),
        height: PILL_H,
      }
    : { left: geo.geom.x, top: geo.geom.y, width: geo.geom.w, height: geo.geom.h }

  /* ── 顶部提示（把所有"读不到 / 对不上"集中到一处）──────────────────── */
  const notices: string[] = []
  if (scan.phase === 'error' && scan.error !== '') notices.push(`扫描出错：${scan.error}`)
  notices.push(...scan.issues)
  if (script.error !== '') notices.push(script.error)
  /* ⚠️ 缺提示词文件时**不往提示条里塞**：这是超集集数的正常中间状态，
     中栏已经用 middleEmpty 说清楚了，再在顶部喊一遍就是噪音（§5.3 的精神）。 */
  if (blk.error !== '' && !promptMissing) notices.push(blk.error)
  notices.push(...blk.issues)
  if (anno.error !== '') notices.push(`批注：${anno.error}`)
  notices.push(...anno.issues)
  if (sessionSource === 'fallback') notices.push('当前没有选中会话，借用的是工作区里的另一个会话；想更准请切到提示词所在工作区的会话。')

  const episodeLabel = episode === null ? '—' : `${episode.episode}`
  const versionLabel = version === null ? '—' : `v${version.version}`

  /**
   * 一张批注卡。
   *
   * @param a - 批注内容（块范围从 `regions` 里取）。
   * @param episodeNo - 给了就显示"第 N 集"（"全部"模式用），并据此定位 / 删除。
   */
  const annotationCard = (a: Annotation, episodeNo?: number): ReactNode => {
    const episodeOfCard = episodeNo ?? episode?.episode ?? 0
    /* 防御：`regions` 万一缺失（例如老宿主返回老格式），也不能让整个工作台崩掉。 */
    const regions = a.regions ?? []
    const first = regions[0]
    return (
      <div key={a.id} className={`pc-acard${a.done ? ' pc-acard-done' : ''}`}>
        <div className="pc-acard-r1">
          {episodeNo === undefined ? null : <span className="pc-tag">第 {episodeNo} 集</span>}
          <span className="pc-tag">{first === undefined ? '（没有区域）' : regionLabel(first)}</span>
          {regions.length > 1 ? <span className="pc-tag">共 {regions.length} 处</span> : null}
          <span className={`pc-tag${a.done ? ' pc-tag-done' : ''}`}>
            {a.done ? `已处理${a.resolvedIn === null ? '' : ` · ${a.resolvedIn}`}` : '未处理'}
          </span>
          <div className="pc-spacer" />
          <button
            type="button"
            className="pc-x"
            title={episodeNo === undefined ? '定位到这些地方' : `定位到第 ${episodeNo} 集`}
            onClick={() => jumpToBlock(episodeOfCard, a.regions)}
          >
            ◎
          </button>
          <button
            type="button"
            className="pc-x"
            title="删除这条批注"
            onClick={() => deleteOne(episodeOfCard, a.id)}
          >
            ✕
          </button>
        </div>
        {regions.map((region, index) => (
          <div key={`${region.paragraph}-${index}`} className="pc-acard-q">
            <span className="pc-acard-ln">{regionLabel(region)}</span>
            “{region.quote.length > 60 ? `${region.quote.slice(0, 60)}…` : region.quote}”
          </div>
        ))}
        <div className="pc-why">{a.problem}</div>
        <div className="pc-ameta">{a.id}</div>
      </div>
    )
  }

  return (
    <>
      <div
        className={`pc-workbench${isMin ? ' pc-min' : ''}`}
        ref={wbRef}
        style={wbStyle}
      >
        <div
          className="pc-wb-hd"
          onMouseDown={(e) => {
            /* 交互控件必须放过：这个 handler 末尾会 preventDefault（拖窗口用），
               而 select/input 的 mousedown 默认行为正是"打开下拉 / 聚焦"。 */
            if ((e.target as HTMLElement).closest('button, select, input, textarea, a, [contenteditable="true"]')) return
            const el = wbRef.current
            if (el === null) return
            if (isMin) {
              const session = geo.beginPillDrag(el.getBoundingClientRect(), e.clientX, e.clientY)
              const down = { x: e.clientX, y: e.clientY }
              let moved = false
              const onMove = (ev: globalThis.MouseEvent): void => {
                if (!moved && Math.abs(ev.clientX - down.x) + Math.abs(ev.clientY - down.y) > 4) moved = true
                if (moved) session.apply(ev.clientX, ev.clientY)
              }
              const onUp = (): void => {
                document.removeEventListener('mousemove', onMove)
                document.removeEventListener('mouseup', onUp)
              }
              document.addEventListener('mousemove', onMove)
              document.addEventListener('mouseup', onUp)
              e.preventDefault()
              return
            }
            if (geo.mode === 'max') return
            startDrag(e, 'move')
          }}
        >
          <span className="pc-grip" aria-hidden>⋮⋮</span>
          <span className="pc-t">提示词对照</span>
          <span className="pc-meta">
            {scan.phase === 'missing' ? '这个工作区还没登记' : `${versionLabel} · 第 ${episodeLabel} 集`}
          </span>
          <div className="pc-spacer" />
          {!isMin && scan.versions.length > 0
            ? (
              <>
                {/* 上一集 / 下一集：放在**版本选择左边**（主人指定的位置），
                    左右方向键也能翻（见上面那段 keydown 监听）。 */}
                <button
                  type="button"
                  className="pc-x"
                  title="上一集（←）"
                  disabled={episodeNav.prev === undefined}
                  onClick={() => { if (episodeNav.prev !== undefined) setPickEpisode(episodeNav.prev.episode) }}
                >
                  ◀
                </button>
                <button
                  type="button"
                  className="pc-x"
                  title="下一集（→）"
                  disabled={episodeNav.next === undefined}
                  onClick={() => { if (episodeNav.next !== undefined) setPickEpisode(episodeNav.next.episode) }}
                >
                  ▶
                </button>
                <select
                  className="pc-sel"
                  title="选版本"
                  value={version?.version ?? ''}
                  onChange={(e) => { setPickVersion(e.target.value); setPickEpisode(null) }}
                >
                  {scan.versions.map(v => (
                    <option key={v.version} value={v.version}>
                      v{v.version}（{v.episodes.length} 集）
                    </option>
                  ))}
                </select>
                <select
                  className="pc-sel"
                  title="选集"
                  value={episode === null ? '' : String(episode.episode)}
                  onChange={(e) => setPickEpisode(Number(e.target.value))}
                  disabled={(version?.episodes.length ?? 0) === 0}
                >
                  {(version?.episodes ?? []).map(x => (
                    <option key={x.episode} value={String(x.episode)}>第 {x.episode} 集</option>
                  ))}
                </select>
              </>
            )
            : null}
          {!isMin
            ? (
              <button
                type="button"
                className="pc-x"
                title="刷新（重读工作台目录、清单、剧本与批注）"
                onClick={() => { wb.reload(); script.reload(); blk.reload(); anno.reload() }}
              >
                ⟳
              </button>
            )
            : null}
          {/* 放大按钮：收起成胶囊时**不显示** —— 胶囊里只留"展开"这一颗，
              多一颗按钮既没用、又把胶囊撑得又宽又乱。 */}
          {!isMin
            ? (
              <button
                type="button"
                className="pc-x"
                title={geo.mode === 'max' ? '还原为默认大小' : '放大（占满整个界面）'}
                onClick={geo.toggleMax}
              >
                {geo.mode === 'max' ? '⤡' : '⛶'}
              </button>
            )
            : null}
          <button
            ref={minBtnRef}
            type="button"
            className="pc-x"
            title={isMin ? '展开工作台' : '收起成一枚小胶囊'}
            onClick={() => geo.toggleMin(minBtnRef.current)}
          >
            {isMin ? '▣' : '—'}
          </button>
        </div>

        {/* 缩放手柄：右边缘 / 下边缘 / 右下角。
            样式在 styles.ts 的 `.pc-rs*`，拖拽走 geometry 的 'w' / 'h' / 'corner'。 */}
        {!isMin
          ? (
            <>
              <div className="pc-rs pc-rs-r" title="拖动调整宽度" onMouseDown={e => startDrag(e, 'w')} />
              <div className="pc-rs pc-rs-b" title="拖动调整高度" onMouseDown={e => startDrag(e, 'h')} />
              <div className="pc-rs pc-rs-br" title="拖动调整大小" onMouseDown={e => startDrag(e, 'corner')} />
            </>
          )
          : null}

        {!isMin && notices.length > 0
          ? (
            <div className="pc-issues pc-issues-err" title={notices.join('\n')}>
              <span className="pc-issues-t">有问题 {notices.length} 条</span>
              <span className="pc-issues-m">{notices[0]}</span>
              {notices.length > 1 ? <span className="pc-issues-n">悬停看全部</span> : null}
            </div>
          )
          : null}

        {!isMin && scan.phase === 'missing'
          ? (
            <div className="pc-onboard">
              <div className="pc-onboard-t">这个工作区还没登记</div>
              <div className="pc-page-d">
                工作台只读 <b>对照工作台/</b> 这个固定目录，它自己不认识文件、也不解析剧本格式。
                把下面这段话发给对话里的 AI，它建好目录、放好剧本与提示词、一集一集登记完，
                这里就会出现剧本与提示词的对照。
              </div>
              <pre className="pc-copy">{REGISTER_PROMPT}</pre>
              <div className="pc-onboard-act">
                <button
                  type="button"
                  className="pc-btn pc-btn-primary"
                  onClick={() => {
                    void navigator.clipboard?.writeText(REGISTER_PROMPT).then(
                      () => setToast('已复制 —— 粘到对话里发给 AI 即可'),
                      () => setToast('复制失败（浏览器拒绝剪贴板）'),
                    )
                  }}
                >
                  复制这段话
                </button>
                <button type="button" className="pc-btn" onClick={() => wb.reload()}>我已经建好了，重新扫描</button>
              </div>
            </div>
          )
          : null}

        {!isMin && scan.phase === 'empty'
          ? (
            <div className="pc-onboard">
              <div className="pc-onboard-t">对照工作台里还没有版本</div>
              <div className="pc-page-d">
                目录建好了，但里面还没有 <b>v1/</b>。让 AI 把第 1 集的提示词与清单登记进来
                （它要用 prompt_compare_write_episode 工具，一次写出提示词与清单两个文件）。
              </div>
              <div className="pc-onboard-act">
                <button type="button" className="pc-btn" onClick={() => wb.reload()}>重新扫描</button>
              </div>
            </div>
          )
          : null}

        {!isMin && scan.phase === 'ready'
          ? (
            <div className="pc-wb-cols" ref={colsRef} onMouseUp={onPromptMouseUp}>
              {/* ① 剧本（只读参考：不可划词、不可批注；它只有一份，不随版本变） */}
              <div className="pc-col pc-col-src" style={{ width: srcW }}>
                <div className="pc-col-hd">
                  <span>剧本</span>
                  <div className="pc-spacer" />
                  <span className="pc-sub">
                    {script.phase === 'ready' ? `${script.totalLines} 行` : script.phase === 'loading' ? '读取中…' : '—'}
                    {' · 只读参考'}
                  </span>
                </div>
                <div className="pc-col-bd" ref={scriptRef}>
                  {script.phase !== 'ready'
                    ? <div className="pc-empty">{script.phase === 'loading' ? '正在读取这一集剧本…' : (script.error || '读不到这一集剧本')}</div>
                    : script.lines.map((text, index) => {
                      const ln = index + 1
                      const cls = `pc-sline${highlightLines.has(ln) ? ' pc-hl' : ''}`
                      return (
                        <div
                          key={ln}
                          data-ln={ln}
                          className={cls}
                          onMouseEnter={() => setHoverLine(ln)}
                          onMouseLeave={() => setHoverLine(prev => (prev === ln ? null : prev))}
                        >
                          <span className="pc-ln">{ln}</span>
                          <span className="pc-stx">{text}</span>
                        </div>
                      )
                    })}
                </div>
              </div>

              <div className="pc-split" onMouseDown={(e) => startColDrag(e, 'src')} title="拖动调整宽度" />

              {/* ② 提示词（按清单渲染成一个个块；划词与批注都在这一栏） */}
              <div className="pc-col pc-col-prompt">
                <div className="pc-col-hd">
                  <span>提示词 · 第 {episodeLabel} 集 · {versionLabel}</span>
                  <div className="pc-spacer" />
                  <span className="pc-sub">
                    {blk.phase === 'ready' ? `${blk.blocks.length} 块` : blk.phase === 'loading' ? '读取中…' : '—'}
                  </span>
                </div>
                <div className="pc-col-bd" ref={promptRef}>
                  {blk.phase !== 'ready'
                    ? <div className="pc-empty">{blk.phase === 'loading' ? '正在读取这一集提示词…' : middleEmpty}</div>
                    : blk.blocks.map(block => (
                      <div
                        key={block.index}
                        data-paragraph={block.index}
                        className={`pc-para${pinnedBlocks.includes(block.index) ? ' pc-para-pinned' : ''}${pendingBlocks.has(block.index) ? ' pc-para-pending' : ''}${hoverBlockIndices.has(block.index) ? ' pc-para-hover' : ''}`}
                        onMouseEnter={() => setHoverBlock(block.index)}
                        onMouseLeave={() => setHoverBlock(prev => (prev === block.index ? null : prev))}
                        onClick={() => setPinnedBlocks(prev => (
                          prev.length === 1 && prev[0] === block.index ? [] : [block.index]
                        ))}
                        title={block.scriptRanges === null ? '剧本里没有对应（新增）' : `对应剧本 ${block.scriptRanges.map(r => `L${r[0]}–L${r[1]}`).join('、')}`}
                      >
                        {/* 块抬头：只放"编号 + 正文首行 + 指向剧本哪儿"，都不许被划进选区
                            （抬头进了选区，quote 里就会混进编号和标签）。 */}
                        <span className="pc-blk-hd">
                          <span className="pc-blk-no">块 {block.index}</span>
                          <span className="pc-blk-anchor" title={block.anchor}>{block.anchor}</span>
                          <span className={`pc-para-src${block.scriptRanges === null ? ' pc-para-new' : ''}`}>
                            {scriptLabelOf(block)}
                          </span>
                        </span>
                        <span className="pc-para-tx">{blockBody(block, missingAnchor.has(block.index))}</span>
                      </div>
                    ))}
                </div>
              </div>

              <div className="pc-split" onMouseDown={(e) => startColDrag(e, 'anno')} title="拖动调整宽度" />

              {/* ③ 批注 */}
              <div className="pc-col pc-col-anno" style={{ width: annoW }}>
                <div className="pc-col-hd">
                  <span>批注</span>
                  <div className="pc-spacer" />
                  {/* 按集看 / 全部看：批注是按集一个文件存的，"全部"会把这一版
                      每一集的批注都读回来并标出集号。 */}
                  <span className="pc-seg">
                    <button
                      type="button"
                      className={annoScope === 'episode' ? 'pc-seg-on' : ''}
                      title="只看当前这一集"
                      onClick={() => setAnnoScope('episode')}
                    >
                      按集
                    </button>
                    <button
                      type="button"
                      className={annoScope === 'all' ? 'pc-seg-on' : ''}
                      title="看这一版所有集的批注"
                      onClick={() => setAnnoScope('all')}
                    >
                      全部
                    </button>
                  </span>
                  <span className="pc-sub">
                    {annoScope === 'all' ? `${allCount} 条` : `${anno.annotations.length} 条`}
                  </span>
                </div>
                <div className="pc-col-bd">
                  <div className="pc-empty">
                    在提示词里划选一段文字（Ctrl 可以连着选几处不连续的），
                    批注框会在选区下方浮出来。
                  </div>

                  {annoScope === 'episode'
                    ? anno.annotations.map(a => annotationCard(a))
                    : (
                      <>
                        {allError === '' ? null : <div className="pc-empty">读批注出错：{allError}</div>}
                        {(version?.episodes ?? []).map(item => {
                          const list = allAnnotations[item.episode] ?? []
                          if (list.length === 0) return null
                          return (
                            <div key={item.episode}>
                              <div className="pc-anno-group">第 {item.episode} 集 · {list.length} 条</div>
                              {list.map(a => annotationCard(a, item.episode))}
                            </div>
                          )
                        })}
                        {allCount === 0 && allError === '' ? <div className="pc-empty">这一版还没有任何批注。</div> : null}
                      </>
                    )}
                </div>

                {/* 下发：流程的下一步。浮层写不进官方输入框，所以是"复制指令"。 */}
                <div className="pc-col-foot">
                  <button
                    type="button"
                    className="pc-btn pc-btn-primary"
                    disabled={sendCount === 0}
                    title={sendCount === 0 ? '还没有批注' : '把这一批批注整理成指令复制到剪贴板'}
                    onClick={sendBatch}
                  >
                    下发 {sendCount} 条批注
                  </button>
                  <div className="pc-foot-hint">
                    {annoScope === 'all' ? '这一版所有集的批注一起下发' : '复制成指令 → 粘到对话里发给 AI'}
                  </div>
                </div>
              </div>
            </div>
          )
          : null}

        {toast === '' ? null : <div className="pc-toast">{toast}</div>}
      </div>

      {/* ══ 批注框：**跟着选区浮出来**（贴在选区下方，夹在视口内）══════════
          为什么不做成批注栏里的固定面板：位置不应该固定，而是根据选择位置而定。
          这里只写问题，**不需要选类型**。 */}
      {pending !== null && pending.open && !isMin
        ? (
          <div
            className="pc-pop2"
            ref={popRef}
            style={{ left: pending.x, top: pending.y, pointerEvents: 'auto' }}
          >
            <div className="pc-pop2-hd">
              <span>
                {pending.regions.length > 1
                  ? `已选 ${pending.regions.length} 处`
                  : (pending.regions[0] === undefined ? '没有选中' : regionLabel(pending.regions[0]))}
              </span>
              <div className="pc-spacer" />
              <span className="pc-pop2-hint">按住 Ctrl 可再选别处</span>
              <button type="button" className="pc-x" title="关掉" onClick={closePending}>✕</button>
            </div>
            <div className="pc-pop2-list">
              {pending.regions.map((region, index) => (
                <div key={`${region.paragraph}-${index}`} className="pc-pop2-q">
                  <span className="pc-acard-ln">{regionLabel(region)}</span>
                  “{region.quote}”
                </div>
              ))}
            </div>
            <textarea
              className="pc-editor-t"
              placeholder="这里有什么问题？（一句话就行）"
              value={problem}
              autoFocus
              onChange={e => setProblem(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) submitAnnotation()
                if (e.key === 'Escape') closePending()
              }}
            />
            <div className="pc-editor-act">
              <button type="button" className="pc-btn" onClick={closePending}>取消</button>
              <div className="pc-spacer" />
              <button type="button" className="pc-btn pc-btn-primary" disabled={anno.saving} onClick={submitAnnotation}>
                {anno.saving ? '保存中…' : '加入批注'}
              </button>
            </div>
          </div>
        )
        : null}
    </>
  )
}

/**
 * 从选区的一个端点往上找"带 data-paragraph 的那个元素"。
 * @param node - 选区的 startContainer / endContainer。
 * @param within - 提示词栏容器（防止把别处的选区算进来）。
 */
function elementOf(node: Node, within: HTMLElement): HTMLElement | null {
  let el: HTMLElement | null = node instanceof HTMLElement ? node : node.parentElement
  while (el !== null && el !== within) {
    if (el.dataset.paragraph !== undefined) return el
    el = el.parentElement
  }
  return null
}
