/**
 * 工作台窗口的「几何」—— 位置、尺寸、三种模式，全部收在这一个 hook 里。
 *
 * 为什么单独抽出来：这块逻辑前后被改坏了六七次，根因是**状态分散**——
 * 位置 / 宽 / 高 / 是否最小化 / 胶囊位置各是一个 state，每个都能独立为 null，
 * 于是出现「有位置没宽高」「mode 已切但几何还是旧的」这类半初始化组合。
 * 收成一个对象 + 明确 mode 之后，任何时刻只有一套完整几何。
 *
 * ── 三条硬规则（都是踩出来的，别违反）──────────────────────────────────
 *
 *  1. **这个元素上永远不写 `transform`**。
 *     DSH 把浮层挂在视口上，元素一旦带 transform，位置和尺寸的读数都会把
 *     变换算进去，同时可能和宿主的行为叠加。表现是「窗口被压小、位置偏移、
 *     读数还对不上」——排查时极具误导性。
 *     所以：移动用 left/top，缩放用 width/height，定位一律不靠 transform。
 *
 *  2. **尺寸永不超出视口**。
 *     把宽度推到接近或超过视口时，观察到的实际渲染尺寸会明显小于设定值
 *     （人家测到过 1180 被渲染成 531）。宁可在设计上留白，也不去踩那条线。
 *
 *  3. **模式切换不改变 `geom`**（除了 max 记录/恢复）。
 *     这样「缩小再展开」必然回到原样，不需要「记住再恢复」那套易错的逻辑。
 */

import { useCallback, useEffect, useRef, useState } from 'react'

/** 窗口几何。四个字段永远同时有值。 */
export interface Geom {
  x: number
  y: number
  w: number
  h: number
}

export type WbMode = 'open' | 'min' | 'max'

export interface WorkbenchGeometry {
  mode: WbMode
  geom: Geom
  /** 最小化时的定位：只用 `right`（见下方 minimizedRight 的说明）。 */
  minRight: number | null
  minTop: number | null
  /** 拖过之后胶囊用的绝对坐标（left/top）。 */
  pillPos: { x: number; y: number } | null
  /** 模式切换的入口。 */
  toggleMin: (minBtn: HTMLElement | null, pillEl?: HTMLElement | null) => void
  toggleMax: () => void
  /** 拖动 / 缩放的起点快照（进入时锁几何，之后按总差值算）。 */
  beginDrag: (box: DOMRect, clientX: number, clientY: number, dragMode: 'move' | 'h' | 'w' | 'corner') => DragSession
  /** 胶囊拖动（最小化状态下允许拖）。 */
  beginPillDrag: (box: DOMRect, clientX: number, clientY: number) => DragSession
  /** 元素引用（拖动时要用它量尺寸，或读实时几何）。 */
  ref: { current: HTMLDivElement | null }
}

export interface DragSession {
  mode: 'move' | 'h' | 'w' | 'corner'
  start: { x: number; y: number; w: number; h: number; px: number; py: number }
  apply: (clientX: number, clientY: number) => void
  finish: () => void
}

/** 侧栏宽度：把候选选择器都量一遍取最宽的那个（官方侧栏可收起，56 或更宽）。 */
function measureSidebar(): number {
  let sideW = 0
  for (const sel of ['[data-sidebar]', 'aside', 'nav', '[class*="sidebar" i]']) {
    for (const el of Array.from(document.querySelectorAll(sel))) {
      const r = el.getBoundingClientRect()
      // 只看「真正占左边那一列」的元素：够高、贴左、宽度合理
      if (r.height > 200 && r.left < 4 && r.width > sideW && r.width < 520) sideW = r.width
    }
  }
  return sideW > 40 ? sideW : 56
}

/**
 * 默认几何：**对齐官方对话区**。
 *
 * 不要靠猜留白（那会变成「8px 到底多宽」这种没法沟通的事），而是：
 *  · 左边界 = 侧栏右边缘 + 12（官方对话也从这一带开始）
 *  · 宽度   = 官方对话的**内容宽**，直接读 DSH 发布的 CSS 变量
 *             `--dsh-chat-content-width`（定义在 ui-conversation 的
 *             ConversationRoot.module.css，公式 clamp(680, 对话列宽×0.64, 920)）
 *    读不到就退回「可用空间 - 一点留白」。
 *
 * 这样工作台看起来就和对话区**一样宽**，主人不用再去量像素。
 * 同时**永不超出视口**（超出会触发宿主的适配行为，见本文件开头的规则 2）。
 */
function defaultGeom(): Geom {
  const x = measureSidebar() + 12
  const y = 56
  const availW = window.innerWidth - x - 16
  const availH = window.innerHeight - y - 16

  let w = availW
  const published = getComputedStyle(document.body).getPropertyValue('--dsh-chat-content-width').trim()
  if (published !== '') {
    /* 该变量可能是 px、也可能是个表达式（clamp/calc）。用一个不可见的 probe 元素
       把它交给浏览器去解析，再量出真实像素宽度。 */
    const probe = document.createElement('div')
    probe.style.cssText = `position:absolute;visibility:hidden;pointer-events:none;width:${published}`
    document.body.appendChild(probe)
    const measured = probe.getBoundingClientRect().width
    probe.remove()
    if (measured > 200) w = measured
  }

  return {
    x,
    y,
    w: Math.max(560, Math.min(w, availW)),
    h: Math.max(320, availH),
  }
}

/** 把值夹在 [lo, hi]。 */
function clamp(v: number, lo: number, hi: number): number {
  return Math.min(Math.max(v, lo), Math.max(lo, hi))
}

/**
 * 最小化胶囊的高度。
 *
 * ⚠️ 必须和 `Workbench.tsx` 里的 `PILL_H` 一致（那边写给元素的 style 用）：
 *    这里只用来把胶囊和「缩小」按钮垂直居中对齐，改一个忘了另一个会差几像素。
 * 2026-09-14：从 24 加到 36 —— 主人反馈原来"太小，有时候找不到"；
 * 36 也正好是样式里圆角 18 的两倍，是一枚完整的胶囊。
 */
const PILL_H = 36

export function useWorkbenchGeometry(): WorkbenchGeometry {
  const ref = useRef<HTMLDivElement | null>(null)
  const [mode, setMode] = useState<WbMode>('open')
  const [geom, setGeom] = useState<Geom>(() => defaultGeom())
  /** max 之前的几何，供还原。 */
  const beforeMax = useRef<Geom | null>(null)
  /** 收缩成胶囊前的尺寸（展开时用它，保证大小一致）。 */
  const beforeMin = useRef<Geom | null>(null)
  const [minRight, setMinRight] = useState<number | null>(null)
  const [minTop, setMinTop] = useState<number | null>(null)
  const [pillPos, setPillPos] = useState<{ x: number; y: number } | null>(null)

  /* 用户还没动过（没拖没缩）时，跟随视口变化刷新默认几何。 */
  const touched = useRef(false)
  useEffect(() => {
    const sync = (): void => { if (!touched.current) setGeom(defaultGeom()) }
    sync()
    window.addEventListener('resize', sync)
    return () => window.removeEventListener('resize', sync)
  }, [])

  /**
   * 缩小 ↔ 展开。
   *
   * ⚠️ 两条要点：
   *
   * 1. **胶囊用 `right` 定位**，不用 left：
   *    胶囊宽度是 `auto`（随内容），没法预先知道多宽；用 left 就得猜一个宽度，
   *    猜错就把右边缘错位、还把按钮挤出盒子（踩过：主人反馈「按钮都看不到了」）。
   *    给 right = 视口宽 - 按钮右边缘，右边缘就精确对齐，左侧也永远够宽。
   *
   * 2. **展开要「在胶囊所在的位置打开」**：
   *    把窗口的右上角对齐到胶囊的右上角，再夹进视口。
   *    不这么做的话，胶囊被拖到右边后一点展开，窗口会跳回左边（主人反馈过）。
   */
  const toggleMin = useCallback((minBtn: HTMLElement | null, pillEl?: HTMLElement | null): void => {
    if (mode === 'min') {
      // 展开：以「胶囊当前的位置」为锚点 —— 右上角对齐
      const pill = pillEl?.getBoundingClientRect()
      const size = beforeMin.current ?? defaultGeom()
      setGeom(() => {
        if (pill === undefined) return size
        return {
          x: clamp(Math.round(pill.right - size.w), 8, Math.max(8, window.innerWidth - size.w - 8)),
          y: clamp(Math.round(pill.top), 8, Math.max(8, window.innerHeight - size.h - 8)),
          w: size.w,
          h: size.h,
        }
      })
      setMode('open')
      setMinRight(null)
      setMinTop(null)
      setPillPos(null)
      return
    }
    // 收起来之前记下当前尺寸，展开时用它（所以展开后大小与收缩前一致）
    beforeMin.current = mode === 'open' ? geom : (beforeMin.current ?? defaultGeom())
    const r = minBtn?.getBoundingClientRect()
    setMinRight(r === undefined ? Math.max(12, window.innerWidth - 400) : Math.round(window.innerWidth - r.right))
    setMinTop(r === undefined ? 56 : Math.round(r.top + r.height / 2 - PILL_H / 2))
    setPillPos(null)   // 每次收起来都先回到「对齐缩小按钮」的默认位置
    setMode('min')
  }, [mode, geom])

  /** 放大 ↔ 还原。放大 = 占满界面（四边 8px）；再点回默认。 */
  const toggleMax = useCallback((): void => {
    if (mode === 'max') {
      setGeom(beforeMax.current ?? defaultGeom())
      touched.current = true
      setMode('open')
      return
    }
    beforeMax.current = geom
    setGeom({ x: 8, y: 8, w: window.innerWidth - 16, h: window.innerHeight - 16 })
    setMinRight(null)
    setMinTop(null)
    setMode('max')
  }, [mode, geom])

  /**
   * 开始一次拖动 / 缩放。
   *
   * 要点：
   *  · 进入时把当前几何**锁成起点快照**，之后按「起点 + 总差值」算 —— 不逐帧累加，
   *    避免误差堆积；也不把每帧变化的状态塞进依赖（那会让监听不断重注册）。
   *  · `apply` 里读的是**快照**，不是最新 state —— 所以拖动过程不依赖 React 的更新时机。
   *  · 位移用 `left/top`，缩放用 `width/height`；**不碰 transform**。
   */
  const beginDrag = useCallback(
    (box: DOMRect, clientX: number, clientY: number, dragMode: 'move' | 'h' | 'w' | 'corner'): DragSession => {
      const start = {
        x: box.left, y: box.top, w: box.width, h: box.height,
        px: clientX, py: clientY,
      }
      // 一旦开始拖，就视为「用户动过了」，后续不再跟随视口刷新默认几何
      touched.current = true
      setMinRight(null)
      setMinTop(null)
      setMode('open')

      return {
        mode: dragMode,
        start,
        apply: (cx: number, cy: number): void => {
          const dx = cx - start.px
          const dy = cy - start.py
          setGeom(() => {
            if (dragMode === 'move') {
              return {
                x: clamp(start.x + dx, 0, Math.max(0, window.innerWidth - start.w)),
                y: clamp(start.y + dy, 0, Math.max(0, window.innerHeight - start.h)),
                w: start.w,
                h: start.h,
              }
            }
            let w = start.w
            let h = start.h
            if (dragMode === 'w' || dragMode === 'corner') {
              w = clamp(start.w + dx, 420, Math.max(420, window.innerWidth - start.x - 12))
            }
            if (dragMode === 'h' || dragMode === 'corner') {
              h = clamp(start.h + dy, 180, Math.max(180, window.innerHeight - start.y - 12))
            }
            return { x: start.x, y: start.y, w, h }
          })
        },
        finish: (): void => { /* 无额外收尾：几何已在 state 里 */ },
      }
    },
    [],
  )

  /**
   * 胶囊（最小化状态）的拖动。
   *
   * 胶囊平时用 `right` 定位（宽度 auto，不知道多宽）；一旦开始拖就**转换成
   * left/top** —— 拖动需要一个稳定的绝对坐标，而 right 会随宽度变化而漂。
   * 宽度从元素实测拿（`getBoundingClientRect`），所以不用猜。
   */
  const beginPillDrag = useCallback((box: DOMRect, clientX: number, clientY: number): DragSession => {
    const start = { x: box.left, y: box.top, w: box.width, h: box.height, px: clientX, py: clientY }
    touched.current = true
    // 从 right 定位切到 left 定位（值相同，视觉上不跳）
    setMinRight(null)
    setMinTop(null)
    setPillPos({ x: start.x, y: start.y })

    return {
      mode: 'move',
      start,
      apply: (cx: number, cy: number): void => {
        setPillPos({
          x: clamp(start.x + cx - start.px, 0, Math.max(0, window.innerWidth - start.w)),
          y: clamp(start.y + cy - start.py, 0, Math.max(0, window.innerHeight - start.h)),
        })
      },
      finish: (): void => { /* 位置已在 state 里 */ },
    }
  }, [])

  return {
    mode, geom, minRight, minTop, pillPos,
    toggleMin, toggleMax, beginDrag, beginPillDrag, ref,
  }
}
