/**
 * 数据 hook：`对照工作台 → 版本/集 → 一集的清单+提示词 → 块 → 批注`。
 *
 * ⚠️ 与 `dsh-novel-script` 的 data.ts **刻意同构、方向相反**（见 workspace.ts 顶上那段）：
 *    那边是"原文（锚点）+ 每版的剧本（作业）"，这边是"剧本（锚点）+ 每版的提示词（作业）"。
 *    所以这里读的是 `剧本/第N集剧本.txt`（**不随版本变**）和
 *    `vN/提示词/第N集提示词.txt`；**不要**再去找 `小说原文.txt`，
 *    也**不要**把剧本塞进版本目录。
 *
 * 界面**按清单切块**（清单里的 `blocks`）：没有"段落"这个概念，
 * 也**不算覆盖范围/覆盖率**（那些明确不做）。
 *
 * 全部只做机械的事：读文件、解析、按清单把提示词正文切成块。
 * 任何读不到 / 读不懂的地方都变成**界面上看得见的错误**，不猜、不降级。
 */

import { useCallback, useEffect, useState } from 'react'
import {
  annotationPath,
  manifestPath,
  promptPath,
  scriptPath,
  type Annotation,
  type ScriptRanges,
} from '../shared/protocol.ts'
/* ⚠️ 切行用 `splitLines`，**不要**在这儿自己写一行 replaceAll：
   `validate.ts` 里点明了"锚点定位、`promptLines`、`scriptRanges` 三处必须用同一个切法，
   否则'第 12 行'在哪一层都会对不上" —— 自己抄一份就是给以后埋雷。 */
import {
  parseAnnotations,
  parseEpisodeManifest,
  splitLines,
  type ValidationIssue,
} from '../shared/validate.ts'
import { loadAnnotations, saveAnnotations } from './annotations.ts'
import {
  EMPTY_SCAN,
  scanWorkbench,
  tryReadText,
  type WorkbenchScan,
  type WorkspaceFilesFace,
} from './workspace.ts'

const messageOf = (error: unknown): string => (error instanceof Error ? error.message : String(error))

/**
 * 一条校验问题 → 界面上的一行字。
 *
 * ⚠️ `BlocksState.issues` / `AnnotationsState.issues` 的契约是 `string[]`，
 *    所以在这里就拼成给人看的句子。`warn` 加「提醒」两个字 ——
 *    不然界面上分不出"这文件根本不能用"和"能用但缺东西"，
 *    两种都得说，但不能长得一样。
 */
const formatIssue = (issue: ValidationIssue): string =>
  issue.level === 'error' ? `${issue.where}：${issue.message}` : `${issue.where}（提醒）：${issue.message}`

/**
 * 把宿主返回的批注**统一成新格式**。
 *
 * ⚠️ 为什么需要（2026-09-14 踩过）：批注格式从扁平的 `paragraph`/`quote`
 *    改成了 `regions` 数组。**宿主半边要重启服务才会更新**，所以会出现
 *    "新客户端 + 老宿主"：老宿主返回老格式，客户端直接读 `a.regions[0]`
 *    就抛异常 —— 整个工作台组件崩掉，**浮窗什么都画不出来**。
 *    这里统一过一遍 `parseAnnotations`（它本来就兼容两种格式），
 *    顺带把坏数据挡在外面，不让一条脏数据把界面搞崩。
 *
 * 注意：这里**只返回能用的批注**，解析时发现的问题被丢掉了。
 * 要在界面上把问题说出来（`AnnotationsState.issues`），得走 `useAnnotations`，
 * 它自己再过一遍 `parseAnnotations` 把 issues 取出来。
 */
export function toAnnotations(value: unknown): Annotation[] {
  return parseAnnotations(value).annotations ?? []
}

/** 加载阶段。 */
export type Phase = 'idle' | 'loading' | 'ready' | 'error'

/* ── 工作台目录扫描 ────────────────────────────────────────────────────── */

export interface WorkbenchState {
  phase: Phase
  scan: WorkbenchScan
  reload: () => void
}

export function useWorkbench(
  files: WorkspaceFilesFace | undefined,
  sessionId?: string,
): WorkbenchState {
  const [scan, setScan] = useState<WorkbenchScan>(EMPTY_SCAN)
  const [phase, setPhase] = useState<Phase>('idle')
  const [nonce, setNonce] = useState(0)

  useEffect(() => {
    if (files === undefined || sessionId === undefined || sessionId === '') {
      setPhase('idle')
      setScan(EMPTY_SCAN)
      return
    }
    const ac = new AbortController()
    setPhase('loading')
    void scanWorkbench(files, sessionId, ac.signal)
      .then((result) => {
        if (ac.signal.aborted) return
        setScan(result)
        setPhase('ready')
      })
      .catch((err: unknown) => {
        if (ac.signal.aborted) return
        /*
         * ⚠️ 这里没有单独的 error 字段（契约里 `WorkbenchState` 只有 phase/scan/reload），
         *    所以错误原文放进 `scan.error`，并把 `scan.phase` 也置成 `error` ——
         *    两个 phase 得一致，不然界面按哪个判断都会打架。
         */
        setScan({ ...EMPTY_SCAN, phase: 'error', error: messageOf(err) })
        setPhase('error')
      })
    return () => { ac.abort() }
  }, [files, sessionId, nonce])

  const reload = useCallback((): void => setNonce(n => n + 1), [])
  return { phase, scan, reload }
}

/* ── 锚点侧：剧本（不随版本变）─────────────────────────────────────────── */

export interface ScriptState {
  phase: Phase
  lines: string[]
  totalLines: number
  error: string
  /**
   * 重新读一次（语义与 `useAnnotations.reload` 一致：nonce 触发 `useEffect` 重跑）。
   *
   * 界面那个"刷新"按钮**不要**再靠换 key 强制重挂中栏 ——
   * 重挂会把版本/集的选择一起重置（主人正看第 3 集、agent 刚改完文件，
   * 一刷新跳回第 1 集）。用这个在原地重读。
   */
  reload: () => void
}

/**
 * `reload` 不是"读出来的数据"，所以内部 state 用去掉它的形状：
 * 这样空值常量不必为了凑类型塞一个假的 `reload`（假函数最容易哪天被真调上）。
 */
type ScriptData = Omit<ScriptState, 'reload'>

const EMPTY_SCRIPT: ScriptData = { phase: 'idle', lines: [], totalLines: 0, error: '' }

/**
 * 读某一集的**剧本**（锚点侧，路径里**没有版本**）。
 *
 * ⚠️ 这是与剧本批注那边最容易搞混的一处：那边 `useNovel` 读的是全局一份的
 *    `小说原文.txt`，这边对应的是**每集一份**的 `剧本/第N集剧本.txt` ——
 *    全局的是"没有版本"，不是"没有集号"，所以参数里必须带 `episode`。
 *
 * `episode` 不是正整数（比如界面还没选集、传了 0）时按 `idle` 处理，
 * 不报错也不去读文件 —— 没选集不是错误。
 */
export function useScript(
  files: WorkspaceFilesFace | undefined,
  sessionId: string | undefined,
  episode: number,
): ScriptState {
  const [state, setState] = useState<ScriptData>(EMPTY_SCRIPT)
  const [nonce, setNonce] = useState(0)

  useEffect(() => {
    if (files === undefined || sessionId === undefined || sessionId === ''
      || !Number.isInteger(episode) || episode < 1) {
      setState(EMPTY_SCRIPT)
      return
    }
    let alive = true
    const ac = new AbortController()
    const rel = scriptPath(episode)
    setState({ ...EMPTY_SCRIPT, phase: 'loading' })
    void tryReadText(files, sessionId, rel, ac.signal)
      .then((text) => {
        if (!alive) return
        if (text === undefined) {
          setState({ ...EMPTY_SCRIPT, phase: 'error', error: `读不到 ${rel} —— 这一集还没有剧本` })
          return
        }
        /* 剧本可能很长、提示词可能超过一页 5000 行，`tryReadText` 会翻页读完。 */
        const lines = splitLines(text)
        setState({ phase: 'ready', lines, totalLines: lines.length, error: '' })
      })
      .catch((err: unknown) => {
        if (!alive) return
        setState({ ...EMPTY_SCRIPT, phase: 'error', error: messageOf(err) })
      })
    return () => { alive = false; ac.abort() }
  }, [files, sessionId, episode, nonce])

  const reload = useCallback((): void => setNonce(n => n + 1), [])
  return { ...state, reload }
}

/* ── 作业侧：一集的清单 + 提示词 → 块 ──────────────────────────────────── */

/** 一个渲染用的提示词块（**清单里的一项**，直接对应界面上的一个块）。 */
export interface BlockView {
  /** 位置序号（**1 基**）—— 批注的 `regions[].paragraph` 挂的就是它。 */
  index: number
  /**
   * 块首行文本（清单里的 `anchor`，用来定位/显示）。
   *
   * **界面就是靠它判"这一块跟文件对不对得上"**（§11：找不到就显示
   * 「清单与文件对不上（找不到这一块）」，**其余块照常渲染**）。
   * 判的时候请用 `validate.ts` 的 `locateAnchor(lines, anchor, promptLines[0])`：
   * 它按**整行精确匹配**，返回 `line: null` 时还带 `matches`，
   * 能分清"一处都没命中"和"命中多处"—— 光比 `lines[0] === anchor` 分不出来。
   * （这里不给 `broken` 之类的标记：契约里的 `BlockView` 就这几个字段，
   *   判据和判法都在，不必再多一个状态。）
   */
  anchor: string
  /** 这一块在**提示词文件**里占的行号区间（清单里工具算好的）。 */
  promptLines: [number, number]
  /** 这一块覆盖**剧本**哪几行；`null` = 剧本里没有对应。 */
  scriptRanges: ScriptRanges | null
  /** 这一块的正文（**含块内空行** —— 块内部不允许空行，但切片出来的原样先给出去）。 */
  text: string
  /** 正文的每一行。 */
  lines: string[]
}

export interface BlocksState {
  phase: Phase
  blocks: BlockView[]
  /**
   * 清单**字段级**的问题（某块 `promptLines` / `scriptRanges` 不合法，已拼成人话）。
   *
   * 清单整体读不动（JSON 坏 / `schema` 不认识）会直接变成 `phase: 'error'`，
   * 不会只在这里记一笔；"锚点找不到"也不在这儿（那是界面按块判的，见 `anchor`）。
   */
  issues: string[]
  error: string
  /** 重新读一次（语义与 `useAnnotations.reload` 一致：nonce 触发 `useEffect` 重跑）。 */
  reload: () => void
}

/** 同 `ScriptData`：`reload` 不进内部 state，空值常量就不用塞假函数。 */
type BlocksData = Omit<BlocksState, 'reload'>

const EMPTY_BLOCKS: BlocksData = { phase: 'idle', blocks: [], issues: [], error: '' }

/**
 * 读某一版某一集的**清单 + 提示词**，按清单把提示词切成块。
 *
 * 剧本（锚点）**不在这里读** —— 块只带 `scriptRanges`（行号），
 * 剧本正文由 `useScript` 单独给界面，两边各读各的、互不拖累。
 */
export function useBlocks(
  files: WorkspaceFilesFace | undefined,
  sessionId: string | undefined,
  version: string,
  episode: number,
): BlocksState {
  const [state, setState] = useState<BlocksData>(EMPTY_BLOCKS)
  const [nonce, setNonce] = useState(0)

  useEffect(() => {
    if (files === undefined || sessionId === undefined || sessionId === ''
      || version === '' || !Number.isInteger(episode) || episode < 1) {
      setState(EMPTY_BLOCKS)
      return
    }
    let alive = true
    const ac = new AbortController()
    setState({ ...EMPTY_BLOCKS, phase: 'loading' })

    void (async () => {
      const manifestRel = manifestPath(version, episode)
      const promptRel = promptPath(version, episode)

      const manifestText = await tryReadText(files, sessionId, manifestRel, ac.signal)
      if (manifestText === undefined) {
        if (alive) setState({ ...EMPTY_BLOCKS, phase: 'error', error: `缺清单文件：${manifestRel}` })
        return
      }
      let raw: unknown
      try {
        raw = JSON.parse(manifestText)
      } catch (error) {
        if (alive) {
          setState({ ...EMPTY_BLOCKS, phase: 'error', error: `${manifestRel} 不是合法 JSON：${messageOf(error)}` })
        }
        return
      }
      const parsed = parseEpisodeManifest(raw)
      if (parsed.manifest === null) {
        /* 整个清单读不懂 → 什么都画不出来，把原因原文说到界面上去。 */
        const detail = parsed.issues.map(formatIssue).join('；')
        if (alive) setState({ ...EMPTY_BLOCKS, phase: 'error', error: `${manifestRel} 读不懂 —— ${detail}` })
        return
      }

      const promptText = await tryReadText(files, sessionId, promptRel, ac.signal)
      if (promptText === undefined) {
        if (alive) setState({ ...EMPTY_BLOCKS, phase: 'error', error: `缺提示词文件：${promptRel}` })
        return
      }

      const lines = splitLines(promptText)
      /*
       * ⚠️ `promptLines` 是工具算的；清单坏了（`[0,0]` 之类）也**不能跳过** ——
       *    块的**位置序号是批注的锚点**，跳过一块，后面所有块的编号都会前移，
       *    批注就指到别的块上去了。坏区间一律切成空块，编号照样占住
       *    （与 `parseEpisodeManifest` 填占位的思路一致）。
       *    区间超出文件行数时 `slice` 会截短 —— "这一块跟文件对不对得上"由界面按块
       *    用 `locateAnchor` 判（§11），这里不替它决定。
       */
      const blocks: BlockView[] = parsed.manifest.blocks.map((block, i) => {
        const [start, end] = block.promptLines
        const body = start >= 1 && end >= start ? lines.slice(start - 1, end) : []
        const promptLines: [number, number] = [start, end]
        return {
          index: i + 1,
          anchor: block.anchor,
          promptLines,
          scriptRanges: block.scriptRanges,
          text: body.join('\n'),
          lines: body,
        }
      })

      if (!alive) return
      /*
       * issues 只收**清单自己读不动**的地方（字段级别的问题）。两条别踩：
       *
       * 1. `manifestWarnings` **不要往这里放**。它是设计文档 §5.3 的**自检信息**
       *    （某块 `scriptRanges` 为 null / 起始行回退 / 与前一块重叠），
       *    是给 **agent** 看的、只报告不阻断；§5.3 与 §10.2 明说界面上
       *    **没有告警面板**。而且 `scriptRanges: null` 本身是**正常情况**
       *    （§5.1："本身就是个值得看的情况"），摊到面板上就是天天喊狼来了。
       *
       * 2. "某块的锚点在文件里找不到"（§11）也**不在这里**判：那是**块级**的事，
       *    由界面按块调 `locateAnchor(lines, block.anchor, block.promptLines[0])`
       *    自己判 —— 只有它能只让那一块显示「清单与文件对不上」、其余块照常渲染。
       *    本 hook 也**不重算** `promptLines`：§2.2 说了不给"用户手工改文件"兜底，
       *    真改了就报出来、让 agent 重新刷一次清单。
       *
       * 于是这里剩下的都是"清单字段不合法"，加一条 issue 就够了，
       * **绝不把整集变成错误**（§11："不崩、不空白"）。
       */
      const issues = parsed.issues.map(formatIssue)
      setState({ phase: 'ready', blocks, issues, error: '' })
    })().catch((err: unknown) => {
      if (!alive) return
      setState({ ...EMPTY_BLOCKS, phase: 'error', error: messageOf(err) })
    })

    return () => { alive = false; ac.abort() }
  }, [files, sessionId, version, episode, nonce])

  const reload = useCallback((): void => setNonce(n => n + 1), [])
  return { ...state, reload }
}

/* ── 批注 ──────────────────────────────────────────────────────────────── */

export interface AnnotationsState {
  phase: Phase
  annotations: Annotation[]
  /** 批注文件里读不动 / 被忽略的坏条目（已拼成人话）。 */
  issues: string[]
  error: string
  /** 保存中（禁用按钮用）。 */
  saving: boolean
  /**
   * 重新从磁盘读一次（**不改内存里已经编辑过的东西**，就是重发一次读取）。
   * 语义与 `useWorkbench.reload` 一致：靠一个 nonce 触发 `useEffect` 重跑。
   */
  reload: () => void
  /** 保存整个列表；成功返回 true。 */
  save(next: readonly Annotation[]): Promise<boolean>
}

export function useAnnotations(
  sessionId: string | undefined,
  version: string,
  episode: number,
): AnnotationsState {
  const [phase, setPhase] = useState<Phase>('idle')
  const [annotations, setAnnotations] = useState<Annotation[]>([])
  const [issues, setIssues] = useState<string[]>([])
  const [error, setError] = useState('')
  const [saving, setSaving] = useState(false)
  const [nonce, setNonce] = useState(0)

  useEffect(() => {
    if (sessionId === undefined || sessionId === '' || version === ''
      || !Number.isInteger(episode) || episode < 1) {
      setPhase('idle')
      setAnnotations([])
      setIssues([])
      return
    }
    let alive = true
    setPhase('loading')
    setError('')
    void loadAnnotations(sessionId, version, episode)
      .then((result) => {
        if (!alive) return
        if (!result.ok) {
          setAnnotations([])
          setIssues([])
          setError(result.error)
          setPhase('error')
          return
        }
        /* 宿主可能返回老格式（老宿主没重启）；统一过一遍，顺手把坏条目变成 issues。 */
        const parsed = parseAnnotations(result.annotations)
        setAnnotations(parsed.annotations ?? [])
        setIssues(parsed.issues.map(formatIssue))
        setPhase('ready')
      })
      .catch((err: unknown) => {
        if (!alive) return
        setAnnotations([])
        setIssues([])
        setError(messageOf(err))
        setPhase('error')
      })
    return () => { alive = false }
  }, [sessionId, version, episode, nonce])

  const reload = useCallback((): void => setNonce(n => n + 1), [])

  const save = useCallback(async (next: readonly Annotation[]): Promise<boolean> => {
    if (sessionId === undefined || sessionId === '' || version === '' || !Number.isInteger(episode) || episode < 1) {
      setError('还没有可用的会话 / 集，存不了批注')
      return false
    }
    setSaving(true)
    try {
      /*
       * 读盘、按 id 合并（磁盘上的 `done` / `resolvedIn` 优先）、写盘**全在宿主侧一次完成**；
       * 浏览器只把当前列表送过去。所以这里**不再**做一次 `mergeAnnotations` ——
       * 两边各合一次，只会把"以谁为准"搅乱。
       */
      const result = await saveAnnotations(sessionId, version, episode, next)
      if (!result.ok) {
        /* 保存失败就说失败，**不假装已保存**（沙箱被拒 / 通道不可用都走这里）。 */
        setError(result.error)
        return false
      }
      const parsed = parseAnnotations(result.annotations)
      setAnnotations(parsed.annotations ?? [])
      setIssues(parsed.issues.map(formatIssue))
      setError('')
      setPhase('ready')
      return true
    } catch (err: unknown) {
      setError(messageOf(err))
      return false
    } finally {
      setSaving(false)
    }
  }, [sessionId, version, episode])

  return { phase, annotations, issues, error, saving, reload, save }
}

/** 批注文件的路径（界面上显示"存到哪儿"用）。 */
export const annotationsPathOf = (version: string, episode: number): string =>
  annotationPath(version, episode)
