/**
 * 数据层：从**固定目录**读工作台 —— 有哪些版本、每个版本有哪些集、缺哪一侧。
 *
 * ⚠️ 与 `dsh-novel-script`（剧本工作台）**刻意同构、方向相反**，照抄之前先看清这句：
 *    那边——锚点是 `小说原文.txt`（一份、不随版本变），作业区是每版的 `剧本/`；
 *    这边——锚点是 `剧本/`（一份、**不随版本变**），作业区是每版的 `提示词/`。
 *    所以扫描出来的形状一样，但"哪边全局、哪边在版本里"正好反着来。
 *    把剧本也扫进每个版本目录，是这一步最容易犯的错。
 *
 * 一条实测出来的契约：`workspaceFiles.list/read` 的**第一个参数是会话 id**，
 * 不是工作区 id —— 会话锚定了工作区根，所以"读哪个工作区"由当前会话决定。
 */

import {
  ANNOTATION_DIR,
  CHANGELOG_FILE,
  MANIFEST_DIR,
  PROMPT_DIR,
  RE_ANNOTATION_FILE,
  RE_MANIFEST_FILE,
  RE_PROMPT_FILE,
  RE_SCRIPT_FILE,
  SCRIPT_DIR,
  WORKBENCH_DIR,
  compareVersions,
  manifestPath,
  promptPath,
  scriptDirPath,
  scriptPath,
  versionOfDir,
  versionPath,
} from '../shared/protocol.ts'

/** 官方 `workspaceFiles` Remote 里我们用到的两个方法（最小面）。 */
export interface WorkspaceFilesFace {
  list(
    sessionId: string,
    path: string,
    signal?: AbortSignal,
  ): Promise<RemoteResult<{
    path: string
    entries: ReadonlyArray<{ name: string; type: 'file' | 'directory' | 'other'; size?: number }>
    truncated: boolean
  }>>
  read(
    sessionId: string,
    path: string,
    range: { offset?: number; limit?: number },
    signal?: AbortSignal,
  ): Promise<RemoteResult<{ text: string; lines: number; offset: number; eof: boolean; absolutePath: string }>>
}

/** 官方 Remote 的返回信封。 */
export type RemoteResult<T> =
  | { readonly ok: true; readonly value: T }
  | { readonly ok: false; readonly error: { readonly code: string; readonly message: string } }

/** 单次读取最多翻多少页（一页默认 5000 行）。 */
const MAX_READ_PAGES = 40

/** 读一页。 */
async function readPage(
  files: WorkspaceFilesFace,
  sessionId: string,
  path: string,
  offset: number,
  signal?: AbortSignal,
): Promise<{ text: string; lines: number; eof: boolean }> {
  const result = await files.read(sessionId, path, { offset }, signal)
  if (!result.ok) throw new Error(`读不了 ${path}：${result.error.code} ${result.error.message}`)
  return { text: result.value.text, lines: result.value.lines, eof: result.value.eof }
}

/**
 * 读一整份文本（**自动翻页**）。
 *
 * ⚠️ `read` 一次只给一页（默认 5000 行），超出只回 `eof:false`，**不报错也不提示** ——
 *    静默截断会让人看到"看起来完整"的半份稿子。这边最容易被截的是**提示词**（作业侧，
 *    一集几千行不稀奇）和**剧本**（锚点侧，几十集攒在一起），两个都踩不得。
 *    分页语义：页间用 `\n` 拼接即可精确还原，行号与物理行号一致。
 */
export async function readText(
  files: WorkspaceFilesFace,
  sessionId: string,
  path: string,
  signal?: AbortSignal,
): Promise<string> {
  const first = await readPage(files, sessionId, path, 1, signal)
  let text = first.text
  let cursor = 1 + first.lines
  let done = first.eof
  let pages = 1
  while (!done && pages < MAX_READ_PAGES) {
    if (signal?.aborted) break
    const page = await readPage(files, sessionId, path, cursor, signal)
    if (page.lines === 0) break
    text += `\n${page.text}`
    cursor += page.lines
    done = page.eof
    pages += 1
  }
  return text
}

/** 读文本；**不存在**时返回 `undefined`（其它错误照抛）。 */
export async function tryReadText(
  files: WorkspaceFilesFace,
  sessionId: string,
  path: string,
  signal?: AbortSignal,
): Promise<string | undefined> {
  try {
    return await readText(files, sessionId, path, signal)
  } catch (error) {
    const text = error instanceof Error ? error.message : String(error)
    if (/not-found|no entry|不存在|FS_NOT_FOUND/i.test(text)) return undefined
    throw error
  }
}

/** 一个目录里有什么。`undefined` = 目录不存在（其它错误照抛）。 */
export interface DirListing {
  dirs: string[]
  files: string[]
}

export async function listDir(
  files: WorkspaceFilesFace,
  sessionId: string,
  path: string,
  signal?: AbortSignal,
): Promise<DirListing | undefined> {
  let result: Awaited<ReturnType<WorkspaceFilesFace['list']>>
  try {
    result = await files.list(sessionId, path, signal)
  } catch (error) {
    const text = error instanceof Error ? error.message : String(error)
    if (/not-found|no entry|不存在|FS_NOT_FOUND/i.test(text)) return undefined
    throw error
  }
  if (!result.ok) {
    if (/not-found|no entry|FS_NOT_FOUND/i.test(`${result.error.code} ${result.error.message}`)) return undefined
    throw new Error(`读不了目录 ${path}：${result.error.code} ${result.error.message}`)
  }
  const dirs: string[] = []
  const fileNames: string[] = []
  for (const entry of result.value.entries) {
    if (entry.type === 'directory') dirs.push(entry.name)
    else if (entry.type === 'file') fileNames.push(entry.name)
  }
  return { dirs, files: fileNames }
}

/* ── 扫描工作台 ────────────────────────────────────────────────────────── */

/** 一个集在**某一版**里的存在情况。 */
export interface EpisodeEntry {
  episode: number
  /**
   * 有剧本文件。
   *
   * ⚠️ 剧本在 `对照工作台/剧本/` 下、**不带版本**，所以同一个集号在每一版的
   *    `hasScript` 必然是同一个值。仍放在这里，是为了让界面**一条记录看全四样**，
   *    不必再回顶层 `scriptEpisodes` 里查一遍。
   */
  hasScript: boolean
  /** 这一版有提示词文件。 */
  hasPrompt: boolean
  /** 这一版有清单文件。 */
  hasManifest: boolean
  /** 这一版有批注文件（**没有不算问题** —— 这一版还没人标注而已）。 */
  hasAnnotations: boolean
}

/** 一个版本。 */
export interface VersionEntry {
  /** 版本号（不带 v），如 `1`。 */
  version: string
  /** 版本目录名，如 `v1`。 */
  dir: string
  episodes: EpisodeEntry[]
  /** 有 `变更记录.txt`。 */
  hasChangelog: boolean
}

/** 扫描结果。 */
export interface WorkbenchScan {
  /**
   * `missing` = 工作区里没有 `对照工作台/`；
   * `empty`   = 有目录，但一个 `v<数字>` 版本目录都没有；
   * `ready`   = 读到了（**不代表没毛病**，缺文件在 `issues` 里）；
   * `error`   = 目录读不了。
   */
  phase: 'missing' | 'ready' | 'empty' | 'error'
  /**
   * 剧本目录里已有的集号（升序）。
   *
   * 为什么单独放在顶层：剧本是**锚点侧、不随版本变**，而某一版可能还没写提示词。
   * 界面要按"剧本有哪些集"列集号时，光看某一版的 `episodes` 是看不全的
   * —— 即使某一版还没有提示词，也能看出剧本有哪些集。
   */
  scriptEpisodes: number[]
  versions: VersionEntry[]
  /** 机械问题：缺文件、集号重复、文件名不认识… */
  issues: string[]
  /** 扫不动时的原因（`phase` 是 `ready`/`empty`/`missing` 时是空串）。 */
  error: string
}

export const EMPTY_SCAN: WorkbenchScan = {
  phase: 'error', scriptEpisodes: [], versions: [], issues: [], error: '还没有开始扫描',
}

/** 一个目录里按集号认出来的文件。 */
interface EpisodeFiles {
  /**
   * 集号 → 文件名**列表**。
   *
   * ⚠️ 为什么是列表不是单值：`第1集…` 和 `第01集…` 都合 `RE_*`（`\d+` 照样吃前导零），
   *    解析出来是**同一个集号**。老实现用 Map 直接覆盖，等于把重号悄悄吞了 ——
   *    界面上少了东西还不报，这种最难查。留列表才能把「第 1 集重复」说出来。
   */
  byEpisode: Map<number, string[]>
  /** 名字压根不认识的（要说出来，但按设计不算错）。 */
  unknown: string[]
}

/** 把目录里的文件名按 `第N集…` 认一遍。 */
function collectEpisodeFiles(names: readonly string[], re: RegExp): EpisodeFiles {
  const byEpisode = new Map<number, string[]>()
  const unknown: string[] = []
  for (const name of names) {
    const m = re.exec(name)
    if (m?.[1] === undefined) { unknown.push(name); continue }
    const episode = Number.parseInt(m[1], 10)
    const list = byEpisode.get(episode)
    if (list === undefined) byEpisode.set(episode, [name])
    else list.push(name)
  }
  return { byEpisode, unknown }
}

/** 某一类文件里"集号重复"的问题文案（对齐设计文档里的说法）。 */
function duplicateIssues(found: Map<number, string[]>, what: string, dirLabel: string): string[] {
  const out: string[] = []
  for (const [episode, names] of found) {
    if (names.length > 1) {
      out.push(`${dirLabel} 第 ${episode} 集重复：有 ${names.length} 个${what}文件（${names.join('、')}）`)
    }
  }
  return out
}

/**
 * 扫 `对照工作台/`：有哪些版本、每一版有哪些集、缺哪一侧。
 *
 * 只做机械检查（文件在不在、集号有没有重号、文件名认不认识），**不判断剧情内容**。
 */
export async function scanWorkbench(
  files: WorkspaceFilesFace,
  sessionId: string,
  signal?: AbortSignal,
): Promise<WorkbenchScan> {
  const root = await listDir(files, sessionId, '.', signal)
  if (root === undefined || !root.dirs.includes(WORKBENCH_DIR)) {
    return { phase: 'missing', scriptEpisodes: [], versions: [], issues: [], error: '' }
  }

  const issues: string[] = []
  const bench = await listDir(files, sessionId, WORKBENCH_DIR, signal)
  if (bench === undefined) {
    return { phase: 'error', scriptEpisodes: [], versions: [], issues: [], error: `读不了 ${WORKBENCH_DIR}/` }
  }

  /* 锚点侧先读掉：剧本在根下、不带版本，后面每一版都要拿它对。 */
  const scriptListing = await listDir(files, sessionId, scriptDirPath(), signal)
  const scriptFiles = collectEpisodeFiles(scriptListing?.files ?? [], RE_SCRIPT_FILE)
  for (const name of scriptFiles.unknown) {
    issues.push(`${SCRIPT_DIR}/${name}：文件名不认识（要写成「第1集剧本.txt」这样）`)
  }
  issues.push(...duplicateIssues(scriptFiles.byEpisode, '剧本', SCRIPT_DIR))
  const scriptEpisodes = [...scriptFiles.byEpisode.keys()].sort((a, b) => a - b)
  if (scriptListing === undefined) {
    issues.push(`缺 ${SCRIPT_DIR}/ 目录 —— 剧本还没放进 ${WORKBENCH_DIR}`)
  } else if (scriptEpisodes.length === 0) {
    issues.push(`${SCRIPT_DIR}/ 里没有剧本文件（要写成「第1集剧本.txt」这样）`)
  }

  const versionDirs = bench.dirs
    .map(dir => ({ dir, version: versionOfDir(dir) }))
    .filter((x): x is { dir: string; version: string } => x.version !== undefined)
    .sort((a, b) => compareVersions(a.version, b.version))

  if (versionDirs.length === 0) {
    /* 一个版本都没有时也要把剧本有哪些集报出去 —— 界面靠它告诉用户"先开 v1"。 */
    return { phase: 'empty', scriptEpisodes, versions: [], issues, error: '' }
  }

  const versions: VersionEntry[] = []
  for (const { dir, version } of versionDirs) {
    const vroot = versionPath(dir)
    const prompts = await listDir(files, sessionId, `${vroot}/${PROMPT_DIR}`, signal)
    const manifests = await listDir(files, sessionId, `${vroot}/${MANIFEST_DIR}`, signal)
    const annotations = await listDir(files, sessionId, `${vroot}/${ANNOTATION_DIR}`, signal)
    const versionRoot = await listDir(files, sessionId, vroot, signal)

    const promptFiles = collectEpisodeFiles(prompts?.files ?? [], RE_PROMPT_FILE)
    const manifestFiles = collectEpisodeFiles(manifests?.files ?? [], RE_MANIFEST_FILE)
    const annotationFiles = collectEpisodeFiles(annotations?.files ?? [], RE_ANNOTATION_FILE)

    /* 不认识的玩意儿要说出来，但不算错（可能是用户自己放的备注之类）。 */
    for (const name of promptFiles.unknown) {
      issues.push(`${dir}/${PROMPT_DIR}/${name}：文件名不认识（要写成「第1集提示词.txt」这样）`)
    }
    for (const name of manifestFiles.unknown) {
      issues.push(`${dir}/${MANIFEST_DIR}/${name}：文件名不认识（要写成「第1集清单.txt」这样）`)
    }
    for (const name of annotationFiles.unknown) {
      issues.push(`${dir}/${ANNOTATION_DIR}/${name}：文件名不认识（要写成「第1集批注.txt」这样）`)
    }
    issues.push(...duplicateIssues(promptFiles.byEpisode, '提示词', dir))
    issues.push(...duplicateIssues(manifestFiles.byEpisode, '清单', dir))
    issues.push(...duplicateIssues(annotationFiles.byEpisode, '批注', dir))

    /*
     * 集号取"这一版自己的三个目录" ∪ "剧本目录"。
     *
     * ⚠️ 为什么把剧本的集号也并进来：剧本是锚点，它有哪些集是**事实**。
     *    只列这一版自己的文件，就会出现"剧本里有第 7 集、v1 还没写提示词，
     *    于是 v1 的列表里根本没有第 7 集" —— 界面上看不出缺的是哪一侧。
     *    并进来以后每条 `EpisodeEntry` 四个标记齐全，"缺哪一侧"一眼就看到。
     *    代价：一版写到一半时会刷出一串"缺提示词"。这是**故意的** ——
     *    设计上不做事务恢复、不做状态机，"中断了就显示缺什么"。
     */
    const all = new Set<number>([
      ...scriptEpisodes,
      ...promptFiles.byEpisode.keys(),
      ...manifestFiles.byEpisode.keys(),
      ...annotationFiles.byEpisode.keys(),
    ])

    const episodes: EpisodeEntry[] = []
    for (const episode of [...all].sort((a, b) => a - b)) {
      const hasScript = scriptFiles.byEpisode.has(episode)
      const hasPrompt = promptFiles.byEpisode.has(episode)
      const hasManifest = manifestFiles.byEpisode.has(episode)
      const hasAnnotations = annotationFiles.byEpisode.has(episode)
      /*
       * 缺哪一侧都**点名到文件**（设计文档 §11）：界面上要能原样念给 agent 听
       * ——"缺提示词文件（对照工作台/v1/提示词/第3集提示词.txt）"比"缺提示词"有用得多。
       * 路径一律走 protocol 里的拼法，别在这儿手搓字符串。
       */
      if (!hasScript) issues.push(`${dir} 第 ${episode} 集：缺剧本文件（${scriptPath(episode)}）`)
      if (!hasPrompt) issues.push(`${dir} 第 ${episode} 集：缺提示词文件（${promptPath(dir, episode)}）`)
      if (!hasManifest) issues.push(`${dir} 第 ${episode} 集：缺清单文件（${manifestPath(dir, episode)}）`)
      /* 批注文件不存在是**正常状态**（这一版还没人标注），不报 —— 报了就天天在喊狼来了。 */
      episodes.push({ episode, hasScript, hasPrompt, hasManifest, hasAnnotations })
    }

    versions.push({
      version,
      dir,
      episodes,
      hasChangelog: versionRoot?.files.includes(CHANGELOG_FILE) === true,
    })
  }

  return { phase: 'ready', scriptEpisodes, versions, issues, error: '' }
}
